    ContainerFleet.add_member(:fleet_role_arn, Smithy::Schema::Shapes::ShapeRef.new(shape: IamRoleArn, location_name: 'FleetRoleArn', traits: {"smithy.api#documentation" => "<p>The unique identifier for an Identity and Access Management (IAM) role with permissions to run your\n            containers on resources that are managed by Amazon GameLift Servers. See <a href=\"https://docs.aws.amazon.com/gamelift/latest/developerguide/setting-up-role.html\">Set up an IAM service\n                role</a>. This fleet property can't be changed.</p>"}))
