    ContainerFleet.add_member(:game_server_container_groups_per_instance, Smithy::Schema::Shapes::ShapeRef.new(shape: GameServerContainerGroupsPerInstance, location_name: 'GameServerContainerGroupsPerInstance', traits: {"smithy.api#documentation" => "<p>The number of times to replicate the game server container group on each fleet\n            instance. </p>"}))
    ContainerFleet.add_member(:maximum_game_server_container_groups_per_instance, Smithy::Schema::Shapes::ShapeRef.new(shape: MaximumGameServerContainerGroupsPerInstance, location_name: 'MaximumGameServerContainerGroupsPerInstance', traits: {"smithy.api#documentation" => "<p>The calculated maximum number of game server container group that can be deployed on\n            each fleet instance. The calculation depends on the resource needs of the container\n            group and the CPU and memory resources of the fleet's instance type.</p>"}))
    ContainerFleet.add_member(:instance_type, Smithy::Schema::Shapes::ShapeRef.new(shape: NonZeroAndMaxString, location_name: 'InstanceType', traits: {"smithy.api#documentation" => "<p>The Amazon EC2 instance type to use for all instances in the fleet. Instance type\n            determines the computing resources and processing power that's available to host your\n            game servers. This includes including CPU, memory, storage, and networking capacity. You\n            can't update this fleet property.</p>"}))
    ContainerFleet.add_member(:billing_type, Smithy::Schema::Shapes::ShapeRef.new(shape: ContainerFleetBillingType, location_name: 'BillingType', traits: {"smithy.api#documentation" => "<p>Indicates whether the fleet uses On-Demand or Spot instances for this fleet. Learn\n            more about when to use <a href=\"https://docs.aws.amazon.com/gamelift/latest/developerguide/gamelift-ec2-instances.html#gamelift-ec2-instances-spot\"> On-Demand versus Spot Instances</a>. You can't update this fleet\n            property.</p>\n         <p>By default, this property is set to <code>ON_DEMAND</code>.</p>"}))
