    ContainerFleet.add_member(:metric_groups, Smithy::Schema::Shapes::ShapeRef.new(shape: MetricGroupList, location_name: 'MetricGroups', traits: {"smithy.api#documentation" => "<p>The name of an Amazon Web Services CloudWatch metric group to add this fleet to. Metric groups\n            aggregate metrics for multiple fleets. </p>"}))
    ContainerFleet.add_member(:new_game_session_protection_policy, Smithy::Schema::Shapes::ShapeRef.new(shape: ProtectionPolicy, location_name: 'NewGameSessionProtectionPolicy', traits: {"smithy.api#documentation" => "<p>Determines whether Amazon GameLift Servers can shut down game sessions on the fleet that are actively\n            running and hosting players. Amazon GameLift Servers might prompt an instance shutdown when scaling down\n            fleet capacity or when retiring unhealthy instances. You can also set game session\n            protection for individual game sessions using <a href=\"gamelift/latest/apireference/API_UpdateGameSession.html\">UpdateGameSession</a>.</p>\n         <ul>\n            <li>\n               <p>\n                  <b>NoProtection</b> -- Game sessions can be shut down\n                    during active gameplay. </p>\n            </li>\n            <li>\n               <p>\n                  <b>FullProtection</b> -- Game sessions in\n                    <code>ACTIVE</code> status can't be shut down.</p>\n            </li>\n         </ul>"}))
    ContainerFleet.add_member(:game_session_creation_limit_policy, Smithy::Schema::Shapes::ShapeRef.new(shape: GameSessionCreationLimitPolicy, location_name: 'GameSessionCreationLimitPolicy', traits: {"smithy.api#documentation" => "<p>A policy that limits the number of game sessions that each individual player can create\n            on instances in this fleet. The limit applies for a specified span of time.</p>"}))
    ContainerFleet.add_member(:status, Smithy::Schema::Shapes::ShapeRef.new(shape: ContainerFleetStatus, location_name: 'Status', traits: {"smithy.api#documentation" => "<p>The current status of the container fleet.</p>\n         <ul>\n            <li>\n               <p>\n                  <code>PENDING</code> -- A new container fleet has been requested.</p>\n            </li>\n            <li>\n               <p>\n                  <code>CREATING</code> -- A new container fleet resource is being created. </p>\n            </li>\n            <li>\n               <p>\n                  <code>CREATED</code> -- A new container fleet resource has been created. No fleet instances\n                    have been deployed.</p>\n            </li>\n            <li>\n               <p>\n                  <code>ACTIVATING</code> -- New container fleet instances are being deployed.</p>\n            </li>\n            <li>\n               <p>\n                  <code>ACTIVE</code> -- The container fleet has been deployed and is ready to host game\n                    sessions.</p>\n            </li>\n            <li>\n               <p>\n                  <code>UPDATING</code> -- Updates to the container fleet is being updated. A deployment is in\n                    progress.</p>\n            </li>\n         </ul>"}))
    ContainerFleet.add_member(:deployment_details, Smithy::Schema::Shapes::ShapeRef.new(shape: DeploymentDetails, location_name: 'DeploymentDetails', traits: {"smithy.api#documentation" => "<p>Information about the most recent deployment for the container fleet.</p>"}))
    ContainerFleet.add_member(:log_configuration, Smithy::Schema::Shapes::ShapeRef.new(shape: LogConfiguration, location_name: 'LogConfiguration', traits: {"smithy.api#documentation" => "<p>The method that is used to collect container logs for the fleet. Amazon GameLift Servers saves all\n            standard output for each container in logs, including game session logs. </p>\n         <ul>\n            <li>\n               <p>\n                  <code>CLOUDWATCH</code> -- Send logs to an Amazon CloudWatch log group that you define. Each container\n                emits a log stream, which is organized in the log group. </p>\n            </li>\n            <li>\n               <p>\n                  <code>S3</code> -- Store logs in an Amazon S3 bucket that you define.</p>\n            </li>\n            <li>\n               <p>\n                  <code>NONE</code> -- Don't collect container logs.</p>\n            </li>\n         </ul>"}))
    ContainerFleet.add_member(:location_attributes, Smithy::Schema::Shapes::ShapeRef.new(shape: ContainerFleetLocationAttributesList, location_name: 'LocationAttributes', traits: {"smithy.api#documentation" => "<p>Information about the container fleet's remote locations where fleet instances are\n            deployed.</p>"}))
