    ContainerGroupDefinition.add_member(:container_group_definition_arn, Smithy::Schema::Shapes::ShapeRef.new(shape: ContainerGroupDefinitionArn, location_name: 'ContainerGroupDefinitionArn', traits: {"smithy.api#documentation" => "<p>The Amazon Resource Name (<a href=\"https://docs.aws.amazon.com/AmazonS3/latest/dev/s3-arn-format.html\">ARN</a>) that is assigned to an Amazon GameLift Servers <code>ContainerGroupDefinition</code> resource. It uniquely identifies \nthe resource across all Amazon Web Services Regions. Format is \n<code>arn:aws:gamelift:[region]::containergroupdefinition/[container group definition name]:[version]</code>.</p>"}))
