    ContainerGroupDefinition.add_member(:operating_system, Smithy::Schema::Shapes::ShapeRef.new(shape: ContainerOperatingSystem, location_name: 'OperatingSystem', traits: {"smithy.api#documentation" => "<p>The platform that all containers in the container group definition run on.</p>\n         <note>\n            <p>Amazon Linux 2 (AL2) will reach end of support on 6/30/2025. See more details in the <a href=\"http://aws.amazon.com/amazon-linux-2/faqs/\">Amazon Linux 2 FAQs</a>. For game\n      servers that are hosted on AL2 and use server SDK version 4.x for Amazon GameLift Servers, first update the game\n        server build to server SDK 5.x, and then deploy to AL2023 instances. See <a href=\"https://docs.aws.amazon.com/gamelift/latest/developerguide/reference-serversdk5-migration.html\"> Migrate to\n          server SDK version 5.</a>\n            </p>\n         </note>"}))
    ContainerGroupDefinition.add_member(:name, Smithy::Schema::Shapes::ShapeRef.new(shape: ContainerGroupDefinitionName, location_name: 'Name', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>A descriptive identifier for the container group definition. The name value is unique in an Amazon Web Services Region.</p>", "smithy.api#required" => {}}))
    ContainerGroupDefinition.add_member(:container_group_type, Smithy::Schema::Shapes::ShapeRef.new(shape: ContainerGroupType, location_name: 'ContainerGroupType', traits: {"smithy.api#documentation" => "<p>The type of container group. Container group type determines how Amazon GameLift Servers deploys the\n      container group on each fleet instance.</p>"}))
    ContainerGroupDefinition.add_member(:total_memory_limit_mebibytes, Smithy::Schema::Shapes::ShapeRef.new(shape: ContainerTotalMemoryLimit, location_name: 'TotalMemoryLimitMebibytes', traits: {"smithy.api#documentation" => "<p>The amount of memory (in MiB) on a fleet instance to allocate for the container group. All\n      containers in the group share these resources. </p>\n         <p>You can set a limit for each container definition in the group. If individual containers\n      have limits, this total value must be greater than any individual container's memory\n      limit.</p>"}))
    ContainerGroupDefinition.add_member(:total_vcpu_limit, Smithy::Schema::Shapes::ShapeRef.new(shape: ContainerTotalVcpuLimit, location_name: 'TotalVcpuLimit', traits: {"smithy.api#documentation" => "<p>The amount of vCPU units on a fleet instance to allocate for the container group (1 vCPU\n      is equal to 1024 CPU units). All containers in the group share these resources. You can set a\n      limit for each container definition in the group. If individual containers have limits, this\n      total value must be equal to or greater than the sum of the limits for each container in the\n      group.</p>"}))
    ContainerGroupDefinition.add_member(:game_server_container_definition, Smithy::Schema::Shapes::ShapeRef.new(shape: GameServerContainerDefinition, location_name: 'GameServerContainerDefinition', traits: {"smithy.api#documentation" => "<p>The definition for the game server container in this group. This property is used only\n      when the container group type is <code>GAME_SERVER</code>. This container definition specifies\n      a container image with the game server build. </p>"}))
