    ContainerHealthCheck.add_member(:interval, Smithy::Schema::Shapes::ShapeRef.new(shape: ContainerHealthCheckInterval, location_name: 'Interval', traits: {"smithy.api#documentation" => "<p>The time period (in seconds) between each health check.</p>"}))
    ContainerHealthCheck.add_member(:retries, Smithy::Schema::Shapes::ShapeRef.new(shape: ContainerHealthCheckRetries, location_name: 'Retries', traits: {"smithy.api#documentation" => "<p>The number of times to retry a failed health check before flagging the container\n      unhealthy. The first run of the command does not count as a retry.</p>"}))
