    ContainerHealthCheck.add_member(:timeout, Smithy::Schema::Shapes::ShapeRef.new(shape: ContainerHealthCheckTimeout, location_name: 'Timeout', traits: {"smithy.api#documentation" => "<p>The time period (in seconds) to wait for a health check to succeed before counting a\n      failed health check. </p>"}))
