    ContainerIdentifier.add_member(:container_name, Smithy::Schema::Shapes::ShapeRef.new(shape: NonZeroAnd128MaxAsciiString, location_name: 'ContainerName', traits: {"smithy.api#documentation" => "<p>The identifier for a container that's running in a compute. </p>"}))
    ContainerIdentifier.add_member(:container_runtime_id, Smithy::Schema::Shapes::ShapeRef.new(shape: NonEmptyString, location_name: 'ContainerRuntimeId', traits: {"smithy.api#documentation" => "<p>The runtime ID for the container that's running in a compute. This value is unique within\n      the compute. It is returned as a <code>ContainerAttribute</code> value in a\n        <code>Compute</code> object.</p>"}))
