    ContainerPortRange.add_member(:to_port, Smithy::Schema::Shapes::ShapeRef.new(shape: PortNumber, location_name: 'ToPort', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>An ending value for the range of allowed port numbers.\n    Port numbers are end-inclusive.\n    This value must be equal to or greater than <code>FromPort</code>.</p>", "smithy.api#required" => {}}))
