    CreateAliasInput.add_member(:description, Smithy::Schema::Shapes::ShapeRef.new(shape: NonZeroAndMaxString, location_name: 'Description', traits: {"smithy.api#documentation" => "<p>A human-readable description of the alias.</p>"}))
    CreateAliasInput.add_member(:routing_strategy, Smithy::Schema::Shapes::ShapeRef.new(shape: RoutingStrategy, location_name: 'RoutingStrategy', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>The routing configuration, including routing type and fleet target, for the alias.\n        </p>", "smithy.api#required" => {}}))
    CreateAliasInput.add_member(:tags, Smithy::Schema::Shapes::ShapeRef.new(shape: TagList, location_name: 'Tags', traits: {"smithy.api#documentation" => "<p>A list of labels to assign to the new alias resource. Tags are developer-defined\n            key-value pairs. Tagging Amazon Web Services resources are useful for resource management, access\n            management and cost allocation. For more information, see <a href=\"https://docs.aws.amazon.com/general/latest/gr/aws_tagging.html\"> Tagging Amazon Web Services Resources</a> in the\n                <i>Amazon Web Services General Reference</i>.</p>"}))
