    CreateBuildInput.add_member(:name, Smithy::Schema::Shapes::ShapeRef.new(shape: NonZeroAndMaxString, location_name: 'Name', traits: {"smithy.api#documentation" => "<p>A descriptive label that is associated with a build. Build names do not need to be unique. You can change this value later. </p>"}))
    CreateBuildInput.add_member(:version, Smithy::Schema::Shapes::ShapeRef.new(shape: NonZeroAndMaxString, location_name: 'Version', traits: {"smithy.api#documentation" => "<p>Version information that is associated with a build or script. Version strings do not need to be unique. You can change this value later. </p>"}))
    CreateBuildInput.add_member(:storage_location, Smithy::Schema::Shapes::ShapeRef.new(shape: S3Location, location_name: 'StorageLocation', traits: {"smithy.api#documentation" => "<p>Information indicating where your game build files are stored. Use this parameter only\n            when creating a build with files stored in an Amazon S3 bucket that you own. The storage\n            location must specify an Amazon S3 bucket name and key. The location must also specify a role\n            ARN that you set up to allow Amazon GameLift Servers to access your Amazon S3 bucket. The S3 bucket and your\n            new build must be in the same Region.</p>\n         <p>If a <code>StorageLocation</code> is specified, the size of your file can be found in\n            your Amazon S3 bucket. Amazon GameLift Servers will report a <code>SizeOnDisk</code> of 0. </p>"}))
    CreateBuildInput.add_member(:operating_system, Smithy::Schema::Shapes::ShapeRef.new(shape: OperatingSystem, location_name: 'OperatingSystem', traits: {"smithy.api#documentation" => "<p>The operating system that your game server binaries run on. This value determines the\n            type of fleet resources that you use for this build. If your game build contains\n            multiple executables, they all must run on the same operating system. You must specify a\n            valid operating system in this request. There is no default value. You can't change a\n            build's operating system later.</p>\n         <note>\n            <p>Amazon Linux 2 (AL2) will reach end of support on 6/30/2025. See more details in \n            the <a href=\"http://aws.amazon.com/amazon-linux-2/faqs/\">Amazon Linux 2 FAQs</a>. \n            For game servers\n                that are hosted on AL2 and use server SDK version 4.x for Amazon GameLift Servers, first update the\n                game server build to server SDK 5.x, and then deploy to AL2023 instances. See\n            <a href=\"https://docs.aws.amazon.com/gamelift/latest/developerguide/reference-serversdk5-migration.html\">\n                Migrate to server SDK version 5.</a>\n            </p>\n         </note>"}))
    CreateBuildInput.add_member(:tags, Smithy::Schema::Shapes::ShapeRef.new(shape: TagList, location_name: 'Tags', traits: {"smithy.api#documentation" => "<p>A list of labels to assign to the new build resource. Tags are developer defined\n            key-value pairs. Tagging Amazon Web Services resources are useful for resource management, access\n            management and cost allocation. For more information, see <a href=\"https://docs.aws.amazon.com/general/latest/gr/aws_tagging.html\"> Tagging Amazon Web Services Resources</a> in the\n                <i>Amazon Web Services General Reference</i>. Once the resource is created, you can\n            use <a href=\"https://docs.aws.amazon.com/gamelift/latest/apireference/API_TagResource.html\">TagResource</a>, <a href=\"https://docs.aws.amazon.com/gamelift/latest/apireference/API_UntagResource.html\">UntagResource</a>, and\n                <a href=\"https://docs.aws.amazon.com/gamelift/latest/apireference/API_ListTagsForResource.html\">ListTagsForResource</a> to add, remove, and view tags. The maximum tag limit\n            may be lower than stated. See the Amazon Web Services General Reference for actual tagging\n            limits.</p>"}))
    CreateBuildInput.add_member(:server_sdk_version, Smithy::Schema::Shapes::ShapeRef.new(shape: ServerSdkVersion, location_name: 'ServerSdkVersion', traits: {"smithy.api#documentation" => "<p>A server SDK version you used when integrating your game server build with Amazon GameLift Servers. For more information see <a href=\"https://docs.aws.amazon.com/gamelift/latest/developerguide/integration-custom-intro.html\">Integrate games\n                with custom game servers</a>. By default Amazon GameLift Servers sets this value to\n                <code>4.0.2</code>.</p>"}))
    CreateBuildInput.type = Types::CreateBuildInput
    CreateBuildOutput.add_member(:build, Smithy::Schema::Shapes::ShapeRef.new(shape: Build, location_name: 'Build', traits: {"smithy.api#documentation" => "<p>The newly created build resource, including a unique build IDs and status. </p>"}))
    CreateBuildOutput.add_member(:upload_credentials, Smithy::Schema::Shapes::ShapeRef.new(shape: AwsCredentials, location_name: 'UploadCredentials', traits: {"smithy.api#documentation" => "<p>This element is returned only when the operation is called without a storage location.\n            It contains credentials to use when you are uploading a build file to an Amazon S3 bucket\n            that is owned by Amazon GameLift Servers. Credentials have a limited life span. To refresh these\n            credentials, call <a href=\"https://docs.aws.amazon.com/gamelift/latest/apireference/API_RequestUploadCredentials.html\">RequestUploadCredentials</a>. </p>"}))
    CreateBuildOutput.add_member(:storage_location, Smithy::Schema::Shapes::ShapeRef.new(shape: S3Location, location_name: 'StorageLocation', traits: {"smithy.api#documentation" => "<p>Amazon S3 location for your game build file, including bucket name and key.</p>"}))
    CreateBuildOutput.type = Types::CreateBuildOutput
    CreateContainerFleetInput.add_member(:fleet_role_arn, Smithy::Schema::Shapes::ShapeRef.new(shape: IamRoleArn, location_name: 'FleetRoleArn', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>The unique identifier for an Identity and Access Management (IAM) role with permissions to run your\n            containers on resources that are managed by Amazon GameLift Servers. Use an IAM service role with the\n                <code>GameLiftContainerFleetPolicy</code> managed policy attached. For more\n            information, see <a href=\"https://docs.aws.amazon.com/gamelift/latest/developerguide/setting-up-role.html\">Set up an IAM service\n                role</a>. You can't change this fleet property after the fleet is\n            created.</p>\n         <p>IAM role ARN values use the following pattern: <code>arn:aws:iam::[Amazon Web Services account]:role/[role name]</code>.</p>", "smithy.api#required" => {}}))
    CreateContainerFleetInput.add_member(:description, Smithy::Schema::Shapes::ShapeRef.new(shape: NonZeroAndMaxString, location_name: 'Description', traits: {"smithy.api#documentation" => "<p>A meaningful description of the container fleet.</p>"}))
    CreateContainerFleetInput.add_member(:game_server_container_group_definition_name, Smithy::Schema::Shapes::ShapeRef.new(shape: ContainerGroupDefinitionNameOrArn, location_name: 'GameServerContainerGroupDefinitionName', traits: {"smithy.api#documentation" => "<p>A container group definition resource that describes how to deploy containers with\n            your game server build and support software onto each fleet instance. You can specify\n            the container group definition's name to use the latest version. Alternatively, provide\n            an ARN value with a specific version number.</p>\n         <p>Create a container group definition by calling \n            <a href=\"https://docs.aws.amazon.com/gamelift/latest/apireference/API_CreateContainerGroupDefinition.html\">CreateContainerGroupDefinition</a>. \n            This operation creates a \n            <a href=\"https://docs.aws.amazon.com/gamelift/latest/apireference/API_ContainerGroupDefinition.html\">ContainerGroupDefinition</a> resource. </p>"}))
    CreateContainerFleetInput.add_member(:per_instance_container_group_definition_name, Smithy::Schema::Shapes::ShapeRef.new(shape: ContainerGroupDefinitionNameOrArn, location_name: 'PerInstanceContainerGroupDefinitionName', traits: {"smithy.api#documentation" => "<p>The name of a container group definition resource that describes a set of axillary\n            software. A fleet instance has one process for executables in this container group. A\n            per-instance container group is optional. You can update the fleet to add or remove a\n            per-instance container group at any time. You can specify the container group\n            definition's name to use the latest version. Alternatively, provide an ARN value with a\n            specific version number. </p>\n         <p>Create a container group definition by calling \n            <a href=\"https://docs.aws.amazon.com/gamelift/latest/apireference/API_CreateContainerGroupDefinition.html\">https://docs.aws.amazon.com/gamelift/latest/apireference/API_CreateContainerGroupDefinition.html</a>. \n            This operation creates a \n            <a href=\"https://docs.aws.amazon.com/gamelift/latest/apireference/API_ContainerGroupDefinition.html\">https://docs.aws.amazon.com/gamelift/latest/apireference/API_ContainerGroupDefinition.html</a> resource.</p>"}))
    CreateContainerFleetInput.add_member(:instance_connection_port_range, Smithy::Schema::Shapes::ShapeRef.new(shape: ConnectionPortRange, location_name: 'InstanceConnectionPortRange', traits: {"smithy.api#documentation" => "<p>The set of port numbers to open on each fleet instance. A fleet's connection ports map\n            to container ports that are configured in the fleet's container group definitions. </p>\n         <p>By default, Amazon GameLift Servers calculates an optimal port range based on your fleet\n            configuration. To use the calculated range, don't set this parameter. The values\n            are:</p>\n         <ul>\n            <li>\n               <p>Port range: 4192 to a number calculated based on your fleet configuration.\n                    Amazon GameLift Servers uses the following formula: <code>4192 + [# of game server container\n                        groups per fleet instance] * [# of container ports in the game server\n                        container group definition] + [# of container ports in the game server\n                        container group definition]</code>\n               </p>\n            </li>\n         </ul>\n         <p>You can also choose to manually set this parameter. When manually setting this\n            parameter, you must use port numbers that match the fleet's inbound permissions port\n            range.</p>\n         <note>\n            <p>If you set values manually, Amazon GameLift Servers no longer calculates a port range for you,\n                even if you later remove the manual settings. </p>\n         </note>"}))
    CreateContainerFleetInput.add_member(:instance_inbound_permissions, Smithy::Schema::Shapes::ShapeRef.new(shape: IpPermissionsList, location_name: 'InstanceInboundPermissions', traits: {"smithy.api#documentation" => "<p>The IP address ranges and port settings that allow inbound traffic to access game\n            server processes and other processes on this fleet. As a best practice, when remotely\n            accessing a fleet instance, we recommend opening ports only when you need them and\n            closing them when you're finished.</p>\n         <p>By default, Amazon GameLift Servers calculates an optimal port range based on your fleet\n            configuration. To use the calculated range, don't set this parameter. The values\n            are:</p>\n         <ul>\n            <li>\n               <p>Protocol: UDP</p>\n            </li>\n            <li>\n               <p>Port range: 4192 to a number calculated based on your fleet configuration. Amazon GameLift Servers uses the\n                    following formula: <code>4192 + [# of game server container groups per fleet\n                        instance] * [# of container ports in the game server container group\n                        definition] + [# of container ports in the game server container group\n                        definition]</code>\n               </p>\n            </li>\n         </ul>\n         <p>You can also choose to manually set this parameter. When manually setting this\n            parameter, you must use port numbers that match the fleet's connection port\n            range.</p>\n         <note>\n            <p>If you set values manually, Amazon GameLift Servers no longer calculates a port range for you,\n                even if you later remove the manual settings. </p>\n         </note>"}))
    CreateContainerFleetInput.add_member(:game_server_container_groups_per_instance, Smithy::Schema::Shapes::ShapeRef.new(shape: GameServerContainerGroupsPerInstance, location_name: 'GameServerContainerGroupsPerInstance', traits: {"smithy.api#documentation" => "<p>The number of times to replicate the game server container group on each fleet\n            instance. </p>\n         <p>By default, Amazon GameLift Servers calculates the maximum number of game server container groups that\n            can fit on each instance. This calculation is based on the CPU and memory resources of\n            the fleet's instance type). To use the calculated maximum, don't set this parameter. If\n            you set this number manually, Amazon GameLift Servers uses your value as long as it's less than the\n            calculated maximum.</p>"}))
    CreateContainerFleetInput.add_member(:instance_type, Smithy::Schema::Shapes::ShapeRef.new(shape: NonZeroAndMaxString, location_name: 'InstanceType', traits: {"smithy.api#documentation" => "<p>The Amazon EC2 instance type to use for all instances in the fleet. For multi-location\n            fleets, the instance type must be available in the home region and all remote locations.\n            Instance type determines the computing resources and processing power that's available\n            to host your game servers. This includes including CPU, memory, storage, and networking\n            capacity. </p>\n         <p>By default, Amazon GameLift Servers selects an instance type that fits the needs of your container\n            groups and is available in all selected fleet locations. You can also choose to manually\n            set this parameter. See <a href=\"http://aws.amazon.com/ec2/instance-types/\">Amazon Elastic Compute Cloud\n                Instance Types</a> for detailed descriptions of Amazon EC2 instance types.</p>\n         <p>You can't update this fleet property later.</p>"}))
    CreateContainerFleetInput.add_member(:billing_type, Smithy::Schema::Shapes::ShapeRef.new(shape: ContainerFleetBillingType, location_name: 'BillingType', traits: {"smithy.api#documentation" => "<p>Indicates whether to use On-Demand or Spot instances for this fleet. Learn more about\n            when to use <a href=\"https://docs.aws.amazon.com/gamelift/latest/developerguide/gamelift-ec2-instances.html#gamelift-ec2-instances-spot\"> On-Demand versus Spot Instances</a>. This fleet property can't be changed after the fleet is created.</p>\n         <p>By default, this property is set to <code>ON_DEMAND</code>.</p>\n         <p>You can't update this fleet property later.</p>"}))
    CreateContainerFleetInput.add_member(:locations, Smithy::Schema::Shapes::ShapeRef.new(shape: LocationConfigurationList, location_name: 'Locations', traits: {"smithy.api#documentation" => "<p>A set of locations to deploy container fleet instances to. You can add any Amazon Web Services\n            Region or Local Zone that's supported by Amazon GameLift Servers. Provide a list of one or more Amazon Web Services\n            Region codes, such as <code>us-west-2</code>, or Local Zone names. Also include the\n            fleet's home Region, which is the Amazon Web Services Region where the fleet is created. For a list of\n            supported Regions and Local Zones, see <a href=\"https://docs.aws.amazon.com/gamelift/latest/developerguide/gamelift-regions.html\"> Amazon GameLift Servers service\n                locations</a> for managed hosting.</p>"}))
    CreateContainerFleetInput.add_member(:metric_groups, Smithy::Schema::Shapes::ShapeRef.new(shape: MetricGroupList, location_name: 'MetricGroups', traits: {"smithy.api#documentation" => "<p>The name of an Amazon Web Services CloudWatch metric group to add this fleet to. You can use a metric group \n            to aggregate metrics for multiple fleets. You can specify an existing metric\n            group name or use a new name to create a new metric group. Each fleet can have only one metric group, \n            but you can change this value at any time. </p>"}))
    CreateContainerFleetInput.add_member(:new_game_session_protection_policy, Smithy::Schema::Shapes::ShapeRef.new(shape: ProtectionPolicy, location_name: 'NewGameSessionProtectionPolicy', traits: {"smithy.api#documentation" => "<p>Determines whether Amazon GameLift Servers can shut down game sessions on the fleet that are actively\n            running and hosting players. Amazon GameLift Servers might prompt an instance shutdown when scaling down\n            fleet capacity or when retiring unhealthy instances. You can also set game session\n            protection for individual game sessions using <a href=\"gamelift/latest/apireference/API_UpdateGameSession.html\">UpdateGameSession</a>.</p>\n         <ul>\n            <li>\n               <p>\n                  <b>NoProtection</b> -- Game sessions can be shut down\n                    during active gameplay. </p>\n            </li>\n            <li>\n               <p>\n                  <b>FullProtection</b> -- Game sessions in\n                        <code>ACTIVE</code> status can't be shut down.</p>\n            </li>\n         </ul>\n         <p>By default, this property is set to <code>NoProtection</code>. </p>"}))
    CreateContainerFleetInput.add_member(:game_session_creation_limit_policy, Smithy::Schema::Shapes::ShapeRef.new(shape: GameSessionCreationLimitPolicy, location_name: 'GameSessionCreationLimitPolicy', traits: {"smithy.api#documentation" => "<p>A policy that limits the number of game sessions that each individual player can create\n            on instances in this fleet. The limit applies for a specified span of time.</p>"}))
    CreateContainerFleetInput.add_member(:log_configuration, Smithy::Schema::Shapes::ShapeRef.new(shape: LogConfiguration, location_name: 'LogConfiguration', traits: {"smithy.api#documentation" => "<p>A method for collecting container logs for the fleet. Amazon GameLift Servers saves all standard\n            output for each container in logs, including game session logs. You can select from the\n            following methods: </p>\n         <ul>\n            <li>\n               <p>\n                  <code>CLOUDWATCH</code> -- Send logs to an Amazon CloudWatch log group that you define. Each container\n                    emits a log stream, which is organized in the log group. </p>\n            </li>\n            <li>\n               <p>\n                  <code>S3</code> -- Store logs in an Amazon S3 bucket that you define.</p>\n            </li>\n            <li>\n               <p>\n                  <code>NONE</code> -- Don't collect container logs.</p>\n            </li>\n         </ul>\n         <p>By default, this property is set to <code>CLOUDWATCH</code>. </p>\n         <p>Amazon GameLift Servers requires permissions to send logs other Amazon Web Services services in your account. These permissions are included in the IAM fleet role for this container fleet (see <code>FleetRoleArn)</code>.</p>"}))
    CreateContainerFleetInput.add_member(:tags, Smithy::Schema::Shapes::ShapeRef.new(shape: TagList, location_name: 'Tags', traits: {"smithy.api#documentation" => "<p>A list of labels to assign to the new fleet resource. Tags are developer-defined\n            key-value pairs. Tagging Amazon Web Services resources are useful for resource management, access\n            management and cost allocation. For more information, see <a href=\"https://docs.aws.amazon.com/general/latest/gr/aws_tagging.html\"> Tagging Amazon Web Services Resources</a> in the\n            <i>Amazon Web Services General Reference</i>.</p>"}))
    CreateContainerFleetInput.type = Types::CreateContainerFleetInput
    CreateContainerFleetOutput.add_member(:container_fleet, Smithy::Schema::Shapes::ShapeRef.new(shape: ContainerFleet, location_name: 'ContainerFleet', traits: {"smithy.api#documentation" => "<p>The properties for the new container fleet, including current status. All fleets are\n            initially placed in <code>PENDING</code> status. </p>"}))
    CreateContainerFleetOutput.type = Types::CreateContainerFleetOutput
    CreateContainerGroupDefinitionInput.add_member(:name, Smithy::Schema::Shapes::ShapeRef.new(shape: ContainerGroupDefinitionName, location_name: 'Name', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>A descriptive identifier for the container group definition. The name value must be unique in an Amazon Web Services Region.</p>", "smithy.api#required" => {}}))
    CreateContainerGroupDefinitionInput.add_member(:container_group_type, Smithy::Schema::Shapes::ShapeRef.new(shape: ContainerGroupType, location_name: 'ContainerGroupType', traits: {"smithy.api#documentation" => "<p>The type of container group being defined. Container group type determines how Amazon GameLift Servers \n      deploys the container group on each fleet instance.</p>\n         <p>Default value: <code>GAME_SERVER</code>\n         </p>"}))
    CreateContainerGroupDefinitionInput.add_member(:total_memory_limit_mebibytes, Smithy::Schema::Shapes::ShapeRef.new(shape: ContainerTotalMemoryLimit, location_name: 'TotalMemoryLimitMebibytes', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>The maximum amount of memory (in MiB) to allocate to the container group. All containers in\n      the group share this memory. If you specify memory limits for an individual container, the\n      total value must be greater than any individual container's memory limit.</p>\n         <p>Default value: 1024</p>", "smithy.api#required" => {}}))
    CreateContainerGroupDefinitionInput.add_member(:total_vcpu_limit, Smithy::Schema::Shapes::ShapeRef.new(shape: ContainerTotalVcpuLimit, location_name: 'TotalVcpuLimit', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>The maximum amount of vCPU units to allocate to the container group (1 vCPU is equal to 1024\n      CPU units). All containers in the group share this memory. If you specify vCPU limits for\n      individual containers, the total value must be equal to or greater than the sum of the CPU\n      limits for all containers in the group.</p>\n         <p>Default value: 1</p>", "smithy.api#required" => {}}))
    CreateContainerGroupDefinitionInput.add_member(:game_server_container_definition, Smithy::Schema::Shapes::ShapeRef.new(shape: GameServerContainerDefinitionInput, location_name: 'GameServerContainerDefinition', traits: {"smithy.api#documentation" => "<p>The definition for the game server container in this group. Define a game server container\n      only when the container group type is <code>GAME_SERVER</code>. Game server containers specify\n      a container image with your game server build. You can pass in your container definitions as a\n      JSON file.</p>"}))
    CreateContainerGroupDefinitionInput.add_member(:support_container_definitions, Smithy::Schema::Shapes::ShapeRef.new(shape: SupportContainerDefinitionInputList, location_name: 'SupportContainerDefinitions', traits: {"smithy.api#documentation" => "<p>One or more definition for support containers in this group. You can define a support\n      container in any type of container group. You can pass in your container definitions as a JSON\n      file.</p>"}))
    CreateContainerGroupDefinitionInput.add_member(:operating_system, Smithy::Schema::Shapes::ShapeRef.new(shape: ContainerOperatingSystem, location_name: 'OperatingSystem', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>The platform that all containers in the group use. Containers in a group must run on the\n      same operating system.</p>\n         <p>Default value: <code>AMAZON_LINUX_2023</code>\n         </p>\n         <note>\n            <p>Amazon Linux 2 (AL2) will reach end of support on 6/30/2025. See more details in the <a href=\"http://aws.amazon.com/amazon-linux-2/faqs/\">Amazon Linux 2 FAQs</a>. For game\n    servers that are hosted on AL2 and use server SDK version 4.x for Amazon GameLift Servers, first update the game\n        server build to server SDK 5.x, and then deploy to AL2023 instances. See <a href=\"https://docs.aws.amazon.com/gamelift/latest/developerguide/reference-serversdk5-migration.html\"> Migrate to\n          server SDK version 5.</a>\n            </p>\n         </note>", "smithy.api#required" => {}}))
    CreateContainerGroupDefinitionInput.add_member(:version_description, Smithy::Schema::Shapes::ShapeRef.new(shape: NonZeroAndMaxString, location_name: 'VersionDescription', traits: {"smithy.api#documentation" => "<p>A description for the initial version of this container group definition. </p>"}))
    CreateContainerGroupDefinitionInput.add_member(:tags, Smithy::Schema::Shapes::ShapeRef.new(shape: TagList, location_name: 'Tags', traits: {"smithy.api#documentation" => "<p>A list of labels to assign to the container group definition resource. Tags are\n      developer-defined key-value pairs. Tagging Amazon Web Services resources are useful for resource management,\n      access management and cost allocation. For more information, see <a href=\"https://docs.aws.amazon.com/general/latest/gr/aws_tagging.html\"> Tagging Amazon Web Services Resources</a> in the\n        <i>Amazon Web Services General Reference</i>. </p>"}))
    CreateContainerGroupDefinitionInput.type = Types::CreateContainerGroupDefinitionInput
    CreateContainerGroupDefinitionOutput.add_member(:container_group_definition, Smithy::Schema::Shapes::ShapeRef.new(shape: ContainerGroupDefinition, location_name: 'ContainerGroupDefinition', traits: {"smithy.api#documentation" => "<p>The properties of the new container group definition resource. You can use this resource to\n      create a container fleet.</p>"}))
    CreateContainerGroupDefinitionOutput.type = Types::CreateContainerGroupDefinitionOutput
    CreateFleetInput.add_member(:name, Smithy::Schema::Shapes::ShapeRef.new(shape: NonZeroAndMaxString, location_name: 'Name', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>A descriptive label that is associated with a fleet. Fleet names do not need to be unique.</p>", "smithy.api#required" => {}}))
    CreateFleetInput.add_member(:description, Smithy::Schema::Shapes::ShapeRef.new(shape: NonZeroAndMaxString, location_name: 'Description', traits: {"smithy.api#documentation" => "<p>A description for the fleet.</p>"}))
    CreateFleetInput.add_member(:build_id, Smithy::Schema::Shapes::ShapeRef.new(shape: BuildIdOrArn, location_name: 'BuildId', traits: {"smithy.api#documentation" => "<p>The unique identifier for a custom game server build to be deployed to a fleet with\n            compute type <code>EC2</code>. You can use either the build ID or ARN. The build must be\n            uploaded to Amazon GameLift Servers and in <code>READY</code> status. This fleet property can't be changed after the fleet is created.</p>"}))
    CreateFleetInput.add_member(:script_id, Smithy::Schema::Shapes::ShapeRef.new(shape: ScriptIdOrArn, location_name: 'ScriptId', traits: {"smithy.api#documentation" => "<p>The unique identifier for a Realtime configuration script to be deployed to a fleet with\n            compute type <code>EC2</code>. You can use either the script ID or ARN. Scripts must be\n            uploaded to Amazon GameLift Servers prior to creating the fleet. This fleet property can't be changed after the fleet is created.</p>"}))
    CreateFleetInput.add_member(:server_launch_path, Smithy::Schema::Shapes::ShapeRef.new(shape: LaunchPathStringModel, location_name: 'ServerLaunchPath', traits: {"smithy.api#documentation" => "<p>\n            <b>This parameter is no longer used.</b> Specify a server\n            launch path using the <code>RuntimeConfiguration</code> parameter. Requests that use\n            this parameter instead continue to be valid.</p>"}))
    CreateFleetInput.add_member(:server_launch_parameters, Smithy::Schema::Shapes::ShapeRef.new(shape: LaunchParametersStringModel, location_name: 'ServerLaunchParameters', traits: {"smithy.api#documentation" => "<p>\n            <b>This parameter is no longer used.</b> Specify server\n            launch parameters using the <code>RuntimeConfiguration</code> parameter. Requests that\n            use this parameter instead continue to be valid.</p>"}))
    CreateFleetInput.add_member(:log_paths, Smithy::Schema::Shapes::ShapeRef.new(shape: StringList, location_name: 'LogPaths', traits: {"smithy.api#documentation" => "<p>\n            <b>This parameter is no longer used.</b> To specify where\n            Amazon GameLift Servers should store log files once a server process shuts down, use the Amazon GameLift Servers server\n            API <code>ProcessReady()</code> and specify one or more directory paths in\n                <code>logParameters</code>. For more information, see <a href=\"https://docs.aws.amazon.com/gamelift/latest/developerguide/gamelift-sdk-server-api.html#gamelift-sdk-server-initialize\">Initialize the server process</a> in the <i>Amazon GameLift Servers Developer\n                Guide</i>. </p>"}))
    CreateFleetInput.add_member(:ec2_instance_type, Smithy::Schema::Shapes::ShapeRef.new(shape: EC2InstanceType, location_name: 'EC2InstanceType', traits: {"smithy.api#documentation" => "<p>The Amazon GameLift Servers-supported Amazon EC2 instance type to use with managed EC2 fleets.\n            Instance type determines the computing resources that will be used to host your game\n            servers, including CPU, memory, storage, and networking capacity. See <a href=\"http://aws.amazon.com/ec2/instance-types/\">Amazon Elastic Compute Cloud Instance Types</a> for\n            detailed descriptions of Amazon EC2 instance types.</p>"}))
    CreateFleetInput.add_member(:ec2_inbound_permissions, Smithy::Schema::Shapes::ShapeRef.new(shape: IpPermissionsList, location_name: 'EC2InboundPermissions', traits: {"smithy.api#documentation" => "<p>The IP address ranges and port settings that allow inbound traffic to access game\n            server processes and other processes on this fleet. Set this parameter for managed EC2 fleets. You can leave this parameter empty when creating the fleet, but you must call \n            <a href=\"https://docs.aws.amazon.com/gamelift/latest/apireference/API_UpdateFleetPortSettings\">https://docs.aws.amazon.com/gamelift/latest/apireference/API_UpdateFleetPortSettings</a> to set it before players can connect to game sessions. \n            As a best practice, we recommend \n            opening ports for remote access only when you need them and closing them when you're finished. \n            For Amazon GameLift Servers Realtime fleets, Amazon GameLift Servers automatically sets TCP and UDP ranges.</p>"}))
    CreateFleetInput.add_member(:new_game_session_protection_policy, Smithy::Schema::Shapes::ShapeRef.new(shape: ProtectionPolicy, location_name: 'NewGameSessionProtectionPolicy', traits: {"smithy.api#documentation" => "<p>The status of termination protection for active game sessions on the fleet. By\n            default, this property is set to <code>NoProtection</code>. You can also set game\n            session protection for an individual game session by calling <a href=\"gamelift/latest/apireference/API_UpdateGameSession.html\">UpdateGameSession</a>.</p>\n         <ul>\n            <li>\n               <p>\n                  <b>NoProtection</b> - Game sessions can be terminated\n                    during active gameplay as a result of a scale-down event. </p>\n            </li>\n            <li>\n               <p>\n                  <b>FullProtection</b> - Game sessions in\n                        <code>ACTIVE</code> status cannot be terminated during a scale-down\n                    event.</p>\n            </li>\n         </ul>"}))
    CreateFleetInput.add_member(:runtime_configuration, Smithy::Schema::Shapes::ShapeRef.new(shape: RuntimeConfiguration, location_name: 'RuntimeConfiguration', traits: {"smithy.api#documentation" => "<p>Instructions for how to launch and run server processes on the fleet. Set runtime\n            configuration for managed EC2 fleets. For an Anywhere fleets, set this\n            parameter only if the fleet is running the Amazon GameLift Servers Agent. The runtime configuration\n            defines one or more server process configurations. Each server process identifies a game\n            executable or Realtime script file and the number of processes to run concurrently. </p>\n         <note>\n            <p>This parameter replaces the parameters <code>ServerLaunchPath</code> and\n                    <code>ServerLaunchParameters</code>, which are still supported for backward\n                compatibility.</p>\n         </note>"}))
    CreateFleetInput.add_member(:resource_creation_limit_policy, Smithy::Schema::Shapes::ShapeRef.new(shape: ResourceCreationLimitPolicy, location_name: 'ResourceCreationLimitPolicy', traits: {"smithy.api#documentation" => "<p>A policy that limits the number of game sessions that an individual player can create\n            on instances in this fleet within a specified span of time.</p>"}))
    CreateFleetInput.add_member(:metric_groups, Smithy::Schema::Shapes::ShapeRef.new(shape: MetricGroupList, location_name: 'MetricGroups', traits: {"smithy.api#documentation" => "<p>The name of an Amazon Web Services CloudWatch metric group to add this fleet to. A metric group is\n            used to aggregate the metrics for multiple fleets. You can specify an existing metric\n            group name or set a new name to create a new metric group. A fleet can be included in\n            only one metric group at a time. </p>"}))
    CreateFleetInput.add_member(:peer_vpc_aws_account_id, Smithy::Schema::Shapes::ShapeRef.new(shape: NonZeroAndMaxString, location_name: 'PeerVpcAwsAccountId', traits: {"smithy.api#documentation" => "<p>Used when peering your Amazon GameLift Servers fleet with a VPC, the unique identifier for the Amazon Web Services\n            account that owns the VPC. You can find your account ID in the Amazon Web Services Management Console under account\n            settings. </p>"}))
    CreateFleetInput.add_member(:peer_vpc_id, Smithy::Schema::Shapes::ShapeRef.new(shape: NonZeroAndMaxString, location_name: 'PeerVpcId', traits: {"smithy.api#documentation" => "<p>A unique identifier for a VPC with resources to be accessed by your Amazon GameLift Servers fleet. The\n            VPC must be in the same Region as your fleet. To look up a VPC ID, use the \n            <a href=\"https://console.aws.amazon.com/vpc/\">VPC Dashboard</a> in the Amazon Web Services Management Console. \n            Learn more about VPC peering in <a href=\"https://docs.aws.amazon.com/gamelift/latest/developerguide/vpc-peering.html\">VPC Peering with Amazon GameLift Servers Fleets</a>.</p>"}))
    CreateFleetInput.add_member(:fleet_type, Smithy::Schema::Shapes::ShapeRef.new(shape: FleetType, location_name: 'FleetType', traits: {"smithy.api#documentation" => "<p>Indicates whether to use On-Demand or Spot instances for this fleet. By default, this\n            property is set to <code>ON_DEMAND</code>. Learn more about when to use <a href=\"https://docs.aws.amazon.com/gamelift/latest/developerguide/gamelift-ec2-instances.html#gamelift-ec2-instances-spot\"> On-Demand versus Spot Instances</a>. This fleet property can't be changed after the fleet is created.</p>"}))
    CreateFleetInput.add_member(:instance_role_arn, Smithy::Schema::Shapes::ShapeRef.new(shape: NonEmptyString, location_name: 'InstanceRoleArn', traits: {"smithy.api#documentation" => "<p>A unique identifier for an IAM role that manages access to your Amazon Web Services services. \n        With an instance role ARN set, any application that runs on an instance in this fleet can assume the role, \n        including install scripts, server processes, and daemons (background processes). Create a role or look up a role's \n        ARN by using the <a href=\"https://console.aws.amazon.com/iam/\">IAM dashboard</a> in the Amazon Web Services Management Console.\n        Learn more about using on-box credentials for your game servers at \n        <a href=\"https://docs.aws.amazon.com/gamelift/latest/developerguide/gamelift-sdk-server-resources.html\">\n        Access external resources from a game server</a>. This fleet property can't be changed after the fleet is created.</p>"}))
    CreateFleetInput.add_member(:certificate_configuration, Smithy::Schema::Shapes::ShapeRef.new(shape: CertificateConfiguration, location_name: 'CertificateConfiguration', traits: {"smithy.api#documentation" => "<p>Prompts Amazon GameLift Servers to generate a TLS/SSL certificate for the fleet. Amazon GameLift Servers uses the\n            certificates to encrypt traffic between game clients and the game servers running on\n            Amazon GameLift Servers. By default, the <code>CertificateConfiguration</code> is <code>DISABLED</code>.\n            You can't change this property after you create the fleet. </p>\n         <p>Certificate Manager (ACM) certificates expire after 13 months.\n            Certificate expiration can cause fleets to fail, preventing players from connecting to\n            instances in the fleet. We recommend you replace fleets before 13 months, consider using\n            fleet aliases for a smooth transition.</p>\n         <note>\n            <p>ACM isn't available in all Amazon Web Services regions. A fleet creation request\n                with certificate generation enabled in an unsupported Region, fails with a 4xx\n                error. For more information about the supported Regions, see <a href=\"https://docs.aws.amazon.com/acm/latest/userguide/acm-regions.html\">Supported\n                    Regions</a> in the <i>Certificate Manager User\n                Guide</i>.</p>\n         </note>"}))
    CreateFleetInput.add_member(:locations, Smithy::Schema::Shapes::ShapeRef.new(shape: LocationConfigurationList, location_name: 'Locations', traits: {"smithy.api#documentation" => "<p>A set of remote locations to deploy additional instances to and manage as a\n            multi-location fleet. Use this parameter when creating a fleet in Amazon Web Services Regions that\n            support multiple locations. You can add any Amazon Web Services Region or Local Zone that's supported\n            by Amazon GameLift Servers. Provide a list of one or more Amazon Web Services Region codes, such as\n                <code>us-west-2</code>, or Local Zone names. When using this parameter, Amazon GameLift Servers\n            requires you to include your home location in the request. For a list of supported\n            Regions and Local Zones, see \n            <a href=\"https://docs.aws.amazon.com/gamelift/latest/developerguide/gamelift-regions.html\">\n                Amazon GameLift Servers service locations</a> for managed hosting.</p>"}))
    CreateFleetInput.add_member(:tags, Smithy::Schema::Shapes::ShapeRef.new(shape: TagList, location_name: 'Tags', traits: {"smithy.api#documentation" => "<p>A list of labels to assign to the new fleet resource. Tags are developer-defined\n            key-value pairs. Tagging Amazon Web Services resources are useful for resource management, access\n            management and cost allocation. For more information, see <a href=\"https://docs.aws.amazon.com/general/latest/gr/aws_tagging.html\"> Tagging Amazon Web Services Resources</a> in the\n                <i>Amazon Web Services General Reference</i>.</p>"}))
    CreateFleetInput.add_member(:compute_type, Smithy::Schema::Shapes::ShapeRef.new(shape: ComputeType, location_name: 'ComputeType', traits: {"smithy.api#documentation" => "<p>The type of compute resource used to host your game servers. </p>\n         <ul>\n            <li>\n               <p>\n                  <code>EC2</code> – The game server build is deployed to Amazon EC2 instances for\n                    cloud hosting. This is the default setting.</p>\n            </li>\n            <li>\n               <p>\n                  <code>ANYWHERE</code> – Game servers \n                    and supporting software are deployed to compute resources that you provide and\n                    manage. With this compute type, you can also set the\n                        <code>AnywhereConfiguration</code> parameter.</p>\n            </li>\n         </ul>"}))
    CreateFleetInput.add_member(:anywhere_configuration, Smithy::Schema::Shapes::ShapeRef.new(shape: AnywhereConfiguration, location_name: 'AnywhereConfiguration', traits: {"smithy.api#documentation" => "<p>Amazon GameLift Servers Anywhere configuration options.</p>"}))
    CreateFleetInput.add_member(:instance_role_credentials_provider, Smithy::Schema::Shapes::ShapeRef.new(shape: InstanceRoleCredentialsProvider, location_name: 'InstanceRoleCredentialsProvider', traits: {"smithy.api#documentation" => "<p>Prompts Amazon GameLift Servers to generate a shared credentials file for the IAM role\n            that's defined in <code>InstanceRoleArn</code>. The shared credentials file is stored on\n            each fleet instance and refreshed as needed. Use shared credentials for applications\n            that are deployed along with the game server executable, if the game server is\n            integrated with server SDK version 5.x. For more information about using shared\n            credentials, see <a href=\"https://docs.aws.amazon.com/gamelift/latest/developerguide/gamelift-sdk-server-resources.html\"> Communicate\n                with other Amazon Web Services resources from your fleets</a>.</p>"}))
    CreateFleetInput.type = Types::CreateFleetInput
    CreateFleetLocationsInput.add_member(:fleet_id, Smithy::Schema::Shapes::ShapeRef.new(shape: FleetIdOrArn, location_name: 'FleetId', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>A unique identifier for the fleet to add locations to. You can use either the fleet ID or ARN value.</p>", "smithy.api#required" => {}}))
    CreateFleetLocationsInput.add_member(:locations, Smithy::Schema::Shapes::ShapeRef.new(shape: LocationConfigurationList, location_name: 'Locations', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>A list of locations to deploy additional instances to and manage as part of the fleet.\n            You can add any Amazon GameLift Servers-supported Amazon Web Services Region as a remote location, in the form of an\n            Amazon Web Services Region code such as <code>us-west-2</code>. </p>", "smithy.api#required" => {}}))
    CreateFleetLocationsInput.type = Types::CreateFleetLocationsInput
    CreateFleetLocationsOutput.add_member(:fleet_id, Smithy::Schema::Shapes::ShapeRef.new(shape: FleetIdOrArn, location_name: 'FleetId', traits: {"smithy.api#documentation" => "<p>A unique identifier for the fleet that was updated with new locations.</p>"}))
    CreateFleetLocationsOutput.add_member(:fleet_arn, Smithy::Schema::Shapes::ShapeRef.new(shape: FleetArn, location_name: 'FleetArn', traits: {"smithy.api#documentation" => "<p>The Amazon Resource Name (<a href=\"https://docs.aws.amazon.com/AmazonS3/latest/dev/s3-arn-format.html\">ARN</a>) that is assigned to a Amazon GameLift Servers fleet resource and uniquely identifies it. ARNs are unique across all Regions. Format is <code>arn:aws:gamelift:<region>::fleet/fleet-a1234567-b8c9-0d1e-2fa3-b45c6d7e8912</code>. </p>"}))
    CreateFleetLocationsOutput.add_member(:location_states, Smithy::Schema::Shapes::ShapeRef.new(shape: LocationStateList, location_name: 'LocationStates', traits: {"smithy.api#documentation" => "<p>The remote locations that are being added to the fleet, and the life-cycle status of\n            each location. For new locations, the status is set to <code>NEW</code>. During location\n            creation, Amazon GameLift Servers updates each location's status as instances are deployed there and\n            prepared for game hosting. This list does not include the fleet home Region or any\n            remote locations that were already added to the fleet.</p>"}))
    CreateFleetLocationsOutput.type = Types::CreateFleetLocationsOutput
    CreateFleetOutput.add_member(:fleet_attributes, Smithy::Schema::Shapes::ShapeRef.new(shape: FleetAttributes, location_name: 'FleetAttributes', traits: {"smithy.api#documentation" => "<p>The properties for the new fleet, including the current status. All fleets are placed\n            in <code>NEW</code> status on creation. </p>"}))
    CreateFleetOutput.add_member(:location_states, Smithy::Schema::Shapes::ShapeRef.new(shape: LocationStateList, location_name: 'LocationStates', traits: {"smithy.api#documentation" => "<p>The fleet's locations and life-cycle status of each location. For new fleets, the\n            status of all locations is set to <code>NEW</code>. During fleet creation, Amazon GameLift Servers\n            updates each location status as instances are deployed there and prepared for game\n            hosting. This list includes an entry for the fleet's home Region. For fleets with no\n            remote locations, only one entry, representing the home Region, is returned.</p>"}))
    CreateFleetOutput.type = Types::CreateFleetOutput
    CreateGameServerGroupInput.add_member(:game_server_group_name, Smithy::Schema::Shapes::ShapeRef.new(shape: GameServerGroupName, location_name: 'GameServerGroupName', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>An identifier for the new game server group. This value is used to generate unique ARN\n            identifiers for the Amazon EC2 Auto Scaling group and the Amazon GameLift Servers FleetIQ game server group. The name\n            must be unique per Region per Amazon Web Services account.</p>", "smithy.api#required" => {}}))
    CreateGameServerGroupInput.add_member(:role_arn, Smithy::Schema::Shapes::ShapeRef.new(shape: IamRoleArn, location_name: 'RoleArn', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>The Amazon Resource Name (<a href=\"https://docs.aws.amazon.com/AmazonS3/latest/dev/s3-arn-format.html\">ARN</a>) for an IAM role that\n            allows Amazon GameLift Servers to access your Amazon EC2 Auto Scaling groups.</p>", "smithy.api#required" => {}}))
    CreateGameServerGroupInput.add_member(:min_size, Smithy::Schema::Shapes::ShapeRef.new(shape: WholeNumber, location_name: 'MinSize', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>The minimum number of instances allowed in the Amazon EC2 Auto Scaling group. During\n            automatic scaling events, Amazon GameLift Servers FleetIQ and Amazon EC2 do not scale down the group below this\n            minimum. In production, this value should be set to at least 1. After the Auto Scaling\n            group is created, update this value directly in the Auto Scaling group using the Amazon Web Services\n            console or APIs.</p>", "smithy.api#required" => {}}))
    CreateGameServerGroupInput.add_member(:max_size, Smithy::Schema::Shapes::ShapeRef.new(shape: PositiveInteger, location_name: 'MaxSize', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>The maximum number of instances allowed in the Amazon EC2 Auto Scaling group. During\n            automatic scaling events, Amazon GameLift Servers FleetIQ and EC2 do not scale up the group above this maximum.\n            After the Auto Scaling group is created, update this value directly in the Auto Scaling\n            group using the Amazon Web Services console or APIs.</p>", "smithy.api#required" => {}}))
    CreateGameServerGroupInput.add_member(:launch_template, Smithy::Schema::Shapes::ShapeRef.new(shape: LaunchTemplateSpecification, location_name: 'LaunchTemplate', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>The Amazon EC2 launch template that contains configuration settings and game server code to\n            be deployed to all instances in the game server group. You can specify the template\n            using either the template name or ID. For help with creating a launch template, see\n                <a href=\"https://docs.aws.amazon.com/autoscaling/ec2/userguide/create-launch-template.html\">Creating a Launch\n                Template for an Auto Scaling Group</a> in the <i>Amazon Elastic Compute Cloud Auto Scaling\n                User Guide</i>. After the Auto Scaling group is created, update this value\n            directly in the Auto Scaling group using the Amazon Web Services console or APIs.</p>\n         <note>\n            <p>If you specify network interfaces in your launch template, you must explicitly set\n                the property <code>AssociatePublicIpAddress</code> to \"true\". If no network\n                interface is specified in the launch template, Amazon GameLift Servers FleetIQ uses your account's default\n                VPC.</p>\n         </note>", "smithy.api#required" => {}}))
    CreateGameServerGroupInput.add_member(:instance_definitions, Smithy::Schema::Shapes::ShapeRef.new(shape: InstanceDefinitions, location_name: 'InstanceDefinitions', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>The Amazon EC2 instance types and sizes to use in the Auto Scaling group. The instance\n            definitions must specify at least two different instance types that are supported by\n            Amazon GameLift Servers FleetIQ. For more information on instance types, see <a href=\"https://docs.aws.amazon.com/AWSEC2/latest/UserGuide/instance-types.html\">EC2 Instance Types</a> in the\n                <i>Amazon Elastic Compute Cloud User Guide</i>. You can optionally specify capacity\n            weighting for each instance type. If no weight value is specified for an instance type,\n            it is set to the default value \"1\". For more information about capacity weighting, see\n                <a href=\"https://docs.aws.amazon.com/autoscaling/ec2/userguide/asg-instance-weighting.html\"> Instance Weighting for\n                Amazon EC2 Auto Scaling</a> in the Amazon EC2 Auto Scaling User Guide.</p>", "smithy.api#required" => {}}))
    CreateGameServerGroupInput.add_member(:auto_scaling_policy, Smithy::Schema::Shapes::ShapeRef.new(shape: GameServerGroupAutoScalingPolicy, location_name: 'AutoScalingPolicy', traits: {"smithy.api#documentation" => "<p>Configuration settings to define a scaling policy for the Auto Scaling group that is\n            optimized for game hosting. The scaling policy uses the metric\n                <code>\"PercentUtilizedGameServers\"</code> to maintain a buffer of idle game servers\n            that can immediately accommodate new games and players. After the Auto Scaling group is\n            created, update this value directly in the Auto Scaling group using the Amazon Web Services console or\n            APIs.</p>"}))
    CreateGameServerGroupInput.add_member(:balancing_strategy, Smithy::Schema::Shapes::ShapeRef.new(shape: BalancingStrategy, location_name: 'BalancingStrategy', traits: {"smithy.api#documentation" => "<p>Indicates how Amazon GameLift Servers FleetIQ balances the use of Spot Instances and On-Demand Instances in the\n            game server group. Method options include the following:</p>\n         <ul>\n            <li>\n               <p>\n                  <code>SPOT_ONLY</code> - Only Spot Instances are used in the game server group. If Spot\n                    Instances are unavailable or not viable for game hosting, the game server group\n                    provides no hosting capacity until Spot Instances can again be used. Until then,\n                    no new instances are started, and the existing nonviable Spot Instances are\n                    terminated (after current gameplay ends) and are not replaced.</p>\n            </li>\n            <li>\n               <p>\n                  <code>SPOT_PREFERRED</code> - (default value) Spot Instances are used whenever available in\n                    the game server group. If Spot Instances are unavailable, the game server group\n                    continues to provide hosting capacity by falling back to On-Demand Instances.\n                    Existing nonviable Spot Instances are terminated (after current gameplay ends)\n                    and are replaced with new On-Demand Instances.</p>\n            </li>\n            <li>\n               <p>\n                  <code>ON_DEMAND_ONLY</code> - Only On-Demand Instances are used in the game\n                    server group. No Spot Instances are used, even when available, while this\n                    balancing strategy is in force.</p>\n            </li>\n         </ul>"}))
    CreateGameServerGroupInput.add_member(:game_server_protection_policy, Smithy::Schema::Shapes::ShapeRef.new(shape: GameServerProtectionPolicy, location_name: 'GameServerProtectionPolicy', traits: {"smithy.api#documentation" => "<p>A flag that indicates whether instances in the game server group are protected \n            from early termination. Unprotected instances that have active game servers running might \n            be terminated during a scale-down event, causing players to be dropped from the game. \n            Protected instances cannot be terminated while there are active game servers running except \n            in the event of a forced game server group deletion (see ). An exception to this is with Spot \n            Instances, which can be terminated by Amazon Web Services regardless of protection status. This property is set to <code>NO_PROTECTION</code> by default.</p>"}))
    CreateGameServerGroupInput.add_member(:vpc_subnets, Smithy::Schema::Shapes::ShapeRef.new(shape: VpcSubnets, location_name: 'VpcSubnets', traits: {"smithy.api#documentation" => "<p>A list of virtual private cloud (VPC) subnets to use with instances in the game server\n            group. By default, all Amazon GameLift Servers FleetIQ-supported Availability Zones are used. You can use this\n            parameter to specify VPCs that you've set up. This property cannot be updated after the\n            game server group is created, and the corresponding Auto Scaling group will always use\n            the property value that is set with this request, even if the Auto Scaling group is\n            updated directly.</p>"}))
    CreateGameServerGroupInput.add_member(:tags, Smithy::Schema::Shapes::ShapeRef.new(shape: TagList, location_name: 'Tags', traits: {"smithy.api#documentation" => "<p>A list of labels to assign to the new game server group resource. Tags are\n            developer-defined key-value pairs. Tagging Amazon Web Services resources is useful for resource\n            management, access management, and cost allocation. For more information, see <a href=\"https://docs.aws.amazon.com/general/latest/gr/aws_tagging.html\"> Tagging Amazon Web Services\n                Resources</a> in the <i>Amazon Web Services General Reference</i>.</p>"}))
    CreateGameServerGroupInput.type = Types::CreateGameServerGroupInput
    CreateGameServerGroupOutput.add_member(:game_server_group, Smithy::Schema::Shapes::ShapeRef.new(shape: GameServerGroup, location_name: 'GameServerGroup', traits: {"smithy.api#documentation" => "<p>The newly created game server group object, including the new ARN value for the Amazon GameLift Servers FleetIQ\n            game server group and the object's status. The Amazon EC2 Auto Scaling group ARN is initially\n            null, since the group has not yet been created. This value is added once the game server\n            group status reaches <code>ACTIVE</code>. </p>"}))
    CreateGameServerGroupOutput.type = Types::CreateGameServerGroupOutput
    CreateGameSessionInput.add_member(:fleet_id, Smithy::Schema::Shapes::ShapeRef.new(shape: FleetIdOrArn, location_name: 'FleetId', traits: {"smithy.api#documentation" => "<p>A unique identifier for the fleet to create a game session in. You can use either the fleet ID or ARN value. Each\n            request must reference either a fleet ID or alias ID, but not both.</p>"}))
    CreateGameSessionInput.add_member(:alias_id, Smithy::Schema::Shapes::ShapeRef.new(shape: AliasIdOrArn, location_name: 'AliasId', traits: {"smithy.api#documentation" => "<p>A unique identifier for the alias associated with the fleet to create a game session in. You can use either the\n            alias ID or ARN value. Each request must reference either a fleet ID or alias ID, but\n            not both.</p>"}))
    CreateGameSessionInput.add_member(:maximum_player_session_count, Smithy::Schema::Shapes::ShapeRef.new(shape: WholeNumber, location_name: 'MaximumPlayerSessionCount', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>The maximum number of players that can be connected simultaneously to the game session.</p>", "smithy.api#required" => {}}))
    CreateGameSessionInput.add_member(:name, Smithy::Schema::Shapes::ShapeRef.new(shape: NonZeroAndMaxString, location_name: 'Name', traits: {"smithy.api#documentation" => "<p>A descriptive label that is associated with a game session. Session names do not need to be unique.</p>"}))
    CreateGameSessionInput.add_member(:game_properties, Smithy::Schema::Shapes::ShapeRef.new(shape: GamePropertyList, location_name: 'GameProperties', traits: {"smithy.api#documentation" => "<p>A set of key-value pairs that can store custom data in a game session.\n  For example: <code>{\"Key\": \"difficulty\", \"Value\": \"novice\"}</code>.\n          For an example, see <a href=\"https://docs.aws.amazon.com/gamelift/latest/developerguide/gamelift-sdk-client-api.html#game-properties-create\">Create a game session with custom properties</a>.                    \n        </p>"}))
    CreateGameSessionInput.add_member(:creator_id, Smithy::Schema::Shapes::ShapeRef.new(shape: NonZeroAndMaxString, location_name: 'CreatorId', traits: {"smithy.api#documentation" => "<p>A unique identifier for a player or entity creating the game session. </p>\n         <p>If you add a resource creation limit policy to a fleet, the\n                <code>CreateGameSession</code> operation requires a <code>CreatorId</code>. Amazon GameLift Servers\n            limits the number of game session creation requests with the same <code>CreatorId</code>\n            in a specified time period.</p>\n         <p>If you your fleet doesn't have a resource creation limit policy and you provide a\n                <code>CreatorId</code> in your <code>CreateGameSession</code> requests, Amazon GameLift Servers\n            limits requests to one request per <code>CreatorId</code> per second.</p>\n         <p>To not limit <code>CreateGameSession</code> requests with the same\n                <code>CreatorId</code>, don't provide a <code>CreatorId</code> in your\n                <code>CreateGameSession</code> request.</p>"}))
    CreateGameSessionInput.add_member(:game_session_id, Smithy::Schema::Shapes::ShapeRef.new(shape: IdStringModel, location_name: 'GameSessionId', traits: {"smithy.api#documentation" => "<p>\n            <i>This parameter is deprecated. Use <code>IdempotencyToken</code>\n                instead.</i>\n         </p>\n         <p>Custom string that uniquely identifies a request for a new game session. Maximum token\n            length is 48 characters. If provided, this string is included in the new game session's\n            ID.</p>"}))
    CreateGameSessionInput.add_member(:idempotency_token, Smithy::Schema::Shapes::ShapeRef.new(shape: IdStringModel, location_name: 'IdempotencyToken', traits: {"smithy.api#documentation" => "<p>Custom string that uniquely identifies the new game session request. This is useful\n            for ensuring that game session requests with the same idempotency token are processed\n            only once. Subsequent requests with the same string return the original\n                <code>GameSession</code> object, with an updated status. Maximum token length is 48\n            characters. If provided, this string is included in the new game session's ID.\n            A game session ARN has the following format: \n    <code>arn:aws:gamelift:<location>::gamesession/<fleet ID>/<custom ID string or idempotency token></code>. Idempotency tokens remain in use for 30 days after a game session has ended;\n            game session objects are retained for this time period and then deleted.</p>"}))
    CreateGameSessionInput.add_member(:game_session_data, Smithy::Schema::Shapes::ShapeRef.new(shape: LargeGameSessionData, location_name: 'GameSessionData', traits: {"smithy.api#documentation" => "<p>A set of custom game session properties, formatted as a single string value. This data is passed to a game server process with a request to start a new game session. For more information, see <a href=\"https://docs.aws.amazon.com/gamelift/latest/developerguide/gamelift-sdk-server-api.html#gamelift-sdk-server-startsession\">Start a game session</a>.</p>"}))
    CreateGameSessionInput.add_member(:location, Smithy::Schema::Shapes::ShapeRef.new(shape: LocationStringModel, location_name: 'Location', traits: {"smithy.api#documentation" => "<p>A fleet's remote location to place the new game session in. If this parameter is not\n            set, the new game session is placed in the fleet's home Region. Specify a remote\n            location with an Amazon Web Services Region code such as <code>us-west-2</code>. When using an\n            Anywhere fleet, this parameter is required and must be set to the Anywhere fleet's\n            custom location.</p>"}))
    CreateGameSessionInput.type = Types::CreateGameSessionInput
    CreateGameSessionOutput.add_member(:game_session, Smithy::Schema::Shapes::ShapeRef.new(shape: GameSession, location_name: 'GameSession', traits: {"smithy.api#documentation" => "<p>Object that describes the newly created game session record.</p>"}))
    CreateGameSessionOutput.type = Types::CreateGameSessionOutput
    CreateGameSessionQueueInput.add_member(:name, Smithy::Schema::Shapes::ShapeRef.new(shape: GameSessionQueueName, location_name: 'Name', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>A descriptive label that is associated with game session queue. Queue names must be unique within each Region.</p>", "smithy.api#required" => {}}))
    CreateGameSessionQueueInput.add_member(:timeout_in_seconds, Smithy::Schema::Shapes::ShapeRef.new(shape: WholeNumber, location_name: 'TimeoutInSeconds', traits: {"smithy.api#documentation" => "<p>The maximum time, in seconds, that a new game session placement request remains in the queue. When a request exceeds this time, the game session placement changes to a <code>TIMED_OUT</code> status. If you don't specify a request timeout, the queue uses a default value.</p>"}))
    CreateGameSessionQueueInput.add_member(:player_latency_policies, Smithy::Schema::Shapes::ShapeRef.new(shape: PlayerLatencyPolicyList, location_name: 'PlayerLatencyPolicies', traits: {"smithy.api#documentation" => "<p>A set of policies that enforce a sliding cap on player latency when processing game sessions placement requests. \n\tUse multiple policies to gradually relax the cap over time if Amazon GameLift Servers can't make a placement.\n\t    Policies are evaluated in order starting with the lowest maximum latency value.</p>"}))
    CreateGameSessionQueueInput.add_member(:destinations, Smithy::Schema::Shapes::ShapeRef.new(shape: GameSessionQueueDestinationList, location_name: 'Destinations', traits: {"smithy.api#documentation" => "<p>A list of fleets and/or fleet aliases that can be used to fulfill game session placement requests in the queue. \n    Destinations are identified by either a fleet ARN or a fleet alias ARN, and are listed in order of placement preference.</p>"}))
    CreateGameSessionQueueInput.add_member(:filter_configuration, Smithy::Schema::Shapes::ShapeRef.new(shape: FilterConfiguration, location_name: 'FilterConfiguration', traits: {"smithy.api#documentation" => "<p>A list of locations where a queue is allowed to place new game sessions. Locations \n            are specified in the form of Amazon Web Services Region codes, such as <code>us-west-2</code>. If this parameter is \n            not set, game sessions can be placed in any queue location. </p>"}))
    CreateGameSessionQueueInput.add_member(:priority_configuration, Smithy::Schema::Shapes::ShapeRef.new(shape: PriorityConfiguration, location_name: 'PriorityConfiguration', traits: {"smithy.api#documentation" => "<p>Custom settings to use when prioritizing destinations and locations for game session placements. This \n            configuration replaces the FleetIQ default prioritization process. Priority types that are not explicitly \n            named will be automatically applied at the end of the prioritization process. </p>"}))
    CreateGameSessionQueueInput.add_member(:custom_event_data, Smithy::Schema::Shapes::ShapeRef.new(shape: QueueCustomEventData, location_name: 'CustomEventData', traits: {"smithy.api#documentation" => "<p>Information to be added to all events that are related to this game session\n            queue.</p>"}))
    CreateGameSessionQueueInput.add_member(:notification_target, Smithy::Schema::Shapes::ShapeRef.new(shape: QueueSnsArnStringModel, location_name: 'NotificationTarget', traits: {"smithy.api#documentation" => "<p>An SNS topic ARN that is set up to receive game session placement notifications. See\n                <a href=\"https://docs.aws.amazon.com/gamelift/latest/developerguide/queue-notification.html\"> Setting up\n                notifications for game session placement</a>.</p>"}))
    CreateGameSessionQueueInput.add_member(:tags, Smithy::Schema::Shapes::ShapeRef.new(shape: TagList, location_name: 'Tags', traits: {"smithy.api#documentation" => "<p>A list of labels to assign to the new game session queue resource. Tags are\n            developer-defined key-value pairs. Tagging Amazon Web Services resources are useful for resource\n            management, access management and cost allocation. For more information, see <a href=\"https://docs.aws.amazon.com/general/latest/gr/aws_tagging.html\"> Tagging Amazon Web Services\n                Resources</a> in the <i>Amazon Web Services General Reference</i>.</p>"}))
    CreateGameSessionQueueInput.type = Types::CreateGameSessionQueueInput
    CreateGameSessionQueueOutput.add_member(:game_session_queue, Smithy::Schema::Shapes::ShapeRef.new(shape: GameSessionQueue, location_name: 'GameSessionQueue', traits: {"smithy.api#documentation" => "<p>An object that describes the newly created game session queue.</p>"}))
    CreateGameSessionQueueOutput.type = Types::CreateGameSessionQueueOutput
    CreateLocationInput.add_member(:location_name, Smithy::Schema::Shapes::ShapeRef.new(shape: CustomInputLocationStringModel, location_name: 'LocationName', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>A descriptive name for the custom location.</p>", "smithy.api#required" => {}}))
    CreateLocationInput.add_member(:tags, Smithy::Schema::Shapes::ShapeRef.new(shape: TagList, location_name: 'Tags', traits: {"smithy.api#documentation" => "<p>A list of labels to assign to the new resource. Tags are developer-defined key-value\n            pairs. Tagging Amazon Web Services resources are useful for resource management, access management,\n            and cost allocation. For more information, see <a href=\"https://docs.aws.amazon.com/general/latest/gr/aws_tagging.html\"> Tagging Amazon Web Services Resources</a> in the\n                <i>Amazon Web Services General Rareference</i>.</p>"}))
    CreateLocationInput.type = Types::CreateLocationInput
    CreateLocationOutput.add_member(:location, Smithy::Schema::Shapes::ShapeRef.new(shape: LocationModel, location_name: 'Location', traits: {"smithy.api#documentation" => "<p>The details of the custom location you created.</p>"}))
    CreateLocationOutput.type = Types::CreateLocationOutput
    CreateMatchmakingConfigurationInput.add_member(:name, Smithy::Schema::Shapes::ShapeRef.new(shape: MatchmakingIdStringModel, location_name: 'Name', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>A unique identifier for the matchmaking configuration. This name is used to identify the configuration associated with a matchmaking\n            request or ticket.</p>", "smithy.api#required" => {}}))
    CreateMatchmakingConfigurationInput.add_member(:description, Smithy::Schema::Shapes::ShapeRef.new(shape: NonZeroAndMaxString, location_name: 'Description', traits: {"smithy.api#documentation" => "<p>A human-readable description of the matchmaking configuration. </p>"}))
    CreateMatchmakingConfigurationInput.add_member(:game_session_queue_arns, Smithy::Schema::Shapes::ShapeRef.new(shape: QueueArnsList, location_name: 'GameSessionQueueArns', traits: {"smithy.api#documentation" => "<p>The Amazon Resource Name (<a href=\"https://docs.aws.amazon.com/AmazonS3/latest/dev/s3-arn-format.html\">ARN</a>) that is assigned to a Amazon GameLift Servers game session queue resource and uniquely identifies it. ARNs are unique across all Regions. Format is <code>arn:aws:gamelift:<region>::gamesessionqueue/<queue name></code>. Queues can be located in any Region. Queues are used to start new\n            Amazon GameLift Servers-hosted game sessions for matches that are created with this matchmaking\n            configuration. If <code>FlexMatchMode</code> is set to <code>STANDALONE</code>, do not\n            set this parameter. </p>"}))
    CreateMatchmakingConfigurationInput.add_member(:request_timeout_seconds, Smithy::Schema::Shapes::ShapeRef.new(shape: MatchmakingRequestTimeoutInteger, location_name: 'RequestTimeoutSeconds', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>The maximum duration, in seconds, that a matchmaking ticket can remain in process\n            before timing out. Requests that fail due to timing out can be resubmitted as\n            needed.</p>", "smithy.api#required" => {}}))
    CreateMatchmakingConfigurationInput.add_member(:acceptance_timeout_seconds, Smithy::Schema::Shapes::ShapeRef.new(shape: MatchmakingAcceptanceTimeoutInteger, location_name: 'AcceptanceTimeoutSeconds', traits: {"smithy.api#documentation" => "<p>The length of time (in seconds) to wait for players to accept a proposed match, if\n            acceptance is required. </p>"}))
    CreateMatchmakingConfigurationInput.add_member(:acceptance_required, Smithy::Schema::Shapes::ShapeRef.new(shape: BooleanModel, location_name: 'AcceptanceRequired', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>A flag that determines whether a match that was created with this configuration must\n            be accepted by the matched players. To require acceptance, set to <code>TRUE</code>.\n            With this option enabled, matchmaking tickets use the status\n                <code>REQUIRES_ACCEPTANCE</code> to indicate when a completed potential match is\n            waiting for player acceptance. </p>", "smithy.api#required" => {}}))
    CreateMatchmakingConfigurationInput.add_member(:rule_set_name, Smithy::Schema::Shapes::ShapeRef.new(shape: MatchmakingRuleSetName, location_name: 'RuleSetName', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>A unique identifier for the matchmaking rule set to use with this configuration. You can use either the rule set name or ARN\n            value. A matchmaking configuration can only use rule sets that are defined in the same\n            Region.</p>", "smithy.api#required" => {}}))
    CreateMatchmakingConfigurationInput.add_member(:notification_target, Smithy::Schema::Shapes::ShapeRef.new(shape: SnsArnStringModel, location_name: 'NotificationTarget', traits: {"smithy.api#documentation" => "<p>An SNS topic ARN that is set up to receive matchmaking notifications. See <a href=\"https://docs.aws.amazon.com/gamelift/latest/flexmatchguide/match-notification.html\">\n                Setting up notifications for matchmaking</a> for more information.</p>"}))
    CreateMatchmakingConfigurationInput.add_member(:additional_player_count, Smithy::Schema::Shapes::ShapeRef.new(shape: WholeNumber, location_name: 'AdditionalPlayerCount', traits: {"smithy.api#documentation" => "<p>The number of player slots in a match to keep open for future players. For example, if the configuration's rule set specifies \n            a match for a single 12-person team, and the additional player count is set to 2, only 10 players are selected for the match. This parameter is not used if <code>FlexMatchMode</code> is set to\n                <code>STANDALONE</code>.</p>"}))
    CreateMatchmakingConfigurationInput.add_member(:custom_event_data, Smithy::Schema::Shapes::ShapeRef.new(shape: CustomEventData, location_name: 'CustomEventData', traits: {"smithy.api#documentation" => "<p>Information to be added to all events related to this matchmaking configuration.\n        </p>"}))
    CreateMatchmakingConfigurationInput.add_member(:game_properties, Smithy::Schema::Shapes::ShapeRef.new(shape: GamePropertyList, location_name: 'GameProperties', traits: {"smithy.api#documentation" => "<p>A set of key-value pairs that can store custom data in a game session.\n  For example: <code>{\"Key\": \"difficulty\", \"Value\": \"novice\"}</code>. This information is added to the new <code>GameSession</code> object that is\n            created for a successful match. This parameter is not used if <code>FlexMatchMode</code>\n            is set to <code>STANDALONE</code>.</p>"}))
    CreateMatchmakingConfigurationInput.add_member(:game_session_data, Smithy::Schema::Shapes::ShapeRef.new(shape: GameSessionData, location_name: 'GameSessionData', traits: {"smithy.api#documentation" => "<p>A set of custom game session properties, formatted as a single string value. This data is passed to a game server process with a request to start a new game session. For more information, see <a href=\"https://docs.aws.amazon.com/gamelift/latest/developerguide/gamelift-sdk-server-api.html#gamelift-sdk-server-startsession\">Start a game session</a>. This information is added to the new <code>GameSession</code> object that is\n            created for a successful match. This parameter is not used if <code>FlexMatchMode</code>\n            is set to <code>STANDALONE</code>.</p>"}))
    CreateMatchmakingConfigurationInput.add_member(:backfill_mode, Smithy::Schema::Shapes::ShapeRef.new(shape: BackfillMode, location_name: 'BackfillMode', traits: {"smithy.api#documentation" => "<p>The method used to backfill game sessions that are created with this matchmaking\n            configuration. Specify <code>MANUAL</code> when your game manages backfill requests\n            manually or does not use the match backfill feature. Specify <code>AUTOMATIC</code> to\n            have Amazon GameLift Servers create a backfill request whenever a game session has one or more open\n            slots. Learn more about manual and automatic backfill in <a href=\"https://docs.aws.amazon.com/gamelift/latest/flexmatchguide/match-backfill.html\"> Backfill Existing Games\n                with FlexMatch</a>. Automatic backfill is not available when\n                <code>FlexMatchMode</code> is set to <code>STANDALONE</code>.</p>"}))
    CreateMatchmakingConfigurationInput.add_member(:flex_match_mode, Smithy::Schema::Shapes::ShapeRef.new(shape: FlexMatchMode, location_name: 'FlexMatchMode', traits: {"smithy.api#documentation" => "<p>Indicates whether this matchmaking configuration is being used with Amazon GameLift Servers hosting or\n            as a standalone matchmaking solution. </p>\n         <ul>\n            <li>\n               <p>\n                  <b>STANDALONE</b> - FlexMatch forms matches and\n                    returns match information, including players and team assignments, in a <a href=\"https://docs.aws.amazon.com/gamelift/latest/flexmatchguide/match-events.html#match-events-matchmakingsucceeded\"> MatchmakingSucceeded</a> event.</p>\n            </li>\n            <li>\n               <p>\n                  <b>WITH_QUEUE</b> - FlexMatch forms matches and uses\n                    the specified Amazon GameLift Servers queue to start a game session for the match. </p>\n            </li>\n         </ul>"}))
    CreateMatchmakingConfigurationInput.add_member(:tags, Smithy::Schema::Shapes::ShapeRef.new(shape: TagList, location_name: 'Tags', traits: {"smithy.api#documentation" => "<p>A list of labels to assign to the new matchmaking configuration resource. Tags are\n            developer-defined key-value pairs. Tagging Amazon Web Services resources are useful for resource\n            management, access management and cost allocation. For more information, see <a href=\"https://docs.aws.amazon.com/general/latest/gr/aws_tagging.html\"> Tagging Amazon Web Services\n                Resources</a> in the <i>Amazon Web Services General Reference</i>.</p>"}))
