    FleetAttributes.add_member(:fleet_arn, Smithy::Schema::Shapes::ShapeRef.new(shape: FleetArn, location_name: 'FleetArn', traits: {"smithy.api#documentation" => "<p>The Amazon Resource Name (<a href=\"https://docs.aws.amazon.com/AmazonS3/latest/dev/s3-arn-format.html\">ARN</a>) that is assigned to a Amazon GameLift Servers fleet resource and uniquely identifies it. ARNs are unique across all Regions. Format is <code>arn:aws:gamelift:<region>::fleet/fleet-a1234567-b8c9-0d1e-2fa3-b45c6d7e8912</code>. In a GameLift fleet ARN, the resource ID matches the <code>FleetId</code>\n            value.</p>"}))
    FleetAttributes.add_member(:fleet_type, Smithy::Schema::Shapes::ShapeRef.new(shape: FleetType, location_name: 'FleetType', traits: {"smithy.api#documentation" => "<p>Indicates whether the fleet uses On-Demand or Spot instances. For more information,\n            see <a href=\"https://docs.aws.amazon.com/gamelift/latest/developerguide/gamelift-ec2-instances.html#gamelift-ec2-instances-spot\"> On-Demand versus Spot Instances</a>. This fleet property can't be changed after the fleet is created.</p>"}))
    FleetAttributes.add_member(:instance_type, Smithy::Schema::Shapes::ShapeRef.new(shape: EC2InstanceType, location_name: 'InstanceType', traits: {"smithy.api#documentation" => "<p>The Amazon EC2 instance type that the fleet uses. Instance type determines the computing\n            resources of each instance in the fleet, including CPU, memory, storage, and networking\n            capacity. See <a href=\"http://aws.amazon.com/ec2/instance-types/\">Amazon Elastic Compute Cloud Instance\n                Types</a> for detailed descriptions. This attribute is used with fleets where\n            <code>ComputeType</code> is <code>EC2</code>.</p>"}))
    FleetAttributes.add_member(:description, Smithy::Schema::Shapes::ShapeRef.new(shape: NonZeroAndMaxString, location_name: 'Description', traits: {"smithy.api#documentation" => "<p>A human-readable description of the fleet.</p>"}))
    FleetAttributes.add_member(:name, Smithy::Schema::Shapes::ShapeRef.new(shape: NonZeroAndMaxString, location_name: 'Name', traits: {"smithy.api#documentation" => "<p>A descriptive label that is associated with a fleet. Fleet names do not need to be unique.</p>"}))
    FleetAttributes.add_member(:creation_time, Smithy::Schema::Shapes::ShapeRef.new(shape: Timestamp, location_name: 'CreationTime', traits: {"smithy.api#documentation" => "<p>A time stamp indicating when this data object was created. Format is a number expressed in Unix time as milliseconds (for example <code>\"1469498468.057\"</code>).</p>"}))
    FleetAttributes.add_member(:termination_time, Smithy::Schema::Shapes::ShapeRef.new(shape: Timestamp, location_name: 'TerminationTime', traits: {"smithy.api#documentation" => "<p>A time stamp indicating when this data object was terminated. Format is a number expressed in Unix time as milliseconds (for example <code>\"1469498468.057\"</code>).</p>"}))
    FleetAttributes.add_member(:status, Smithy::Schema::Shapes::ShapeRef.new(shape: FleetStatus, location_name: 'Status', traits: {"smithy.api#documentation" => "<p>Current status of the fleet. Possible fleet statuses include the following:</p>\n         <ul>\n            <li>\n               <p>NEW -- A new fleet resource has been defined and Amazon GameLift Servers has started creating the fleet. \n                    Desired instances is set to 1. </p>\n            </li>\n            <li>\n               <p>DOWNLOADING/VALIDATING/BUILDING -- Amazon GameLift Servers is download the game server build,\n                    running install scripts, and then validating the build files. When complete,\n                    Amazon GameLift Servers launches a fleet instance. </p>\n            </li>\n            <li>\n               <p>ACTIVATING -- Amazon GameLift Servers is launching a game server process and testing its\n                    connectivity with the Amazon GameLift Servers service.</p>\n            </li>\n            <li>\n               <p>ACTIVE -- The fleet is now ready to host game sessions.</p>\n            </li>\n            <li>\n               <p>ERROR -- An error occurred when downloading,\n                    validating, building, or activating the fleet.</p>\n            </li>\n            <li>\n               <p>DELETING -- Hosts are responding to a delete fleet request.</p>\n            </li>\n            <li>\n               <p>TERMINATED -- The fleet no longer exists.</p>\n            </li>\n         </ul>"}))
    FleetAttributes.add_member(:build_id, Smithy::Schema::Shapes::ShapeRef.new(shape: BuildId, location_name: 'BuildId', traits: {"smithy.api#documentation" => "<p>A unique identifier for the build resource that is deployed on instances in this fleet. This attribute is used with\n        fleets where <code>ComputeType</code> is \"EC2\".</p>"}))
    FleetAttributes.add_member(:build_arn, Smithy::Schema::Shapes::ShapeRef.new(shape: BuildArn, location_name: 'BuildArn', traits: {"smithy.api#documentation" => "<p> The Amazon Resource Name (<a href=\"https://docs.aws.amazon.com/AmazonS3/latest/dev/s3-arn-format.html\">ARN</a>) associated with the Amazon GameLift Servers build resource that is deployed on instances in\n            this fleet. In a GameLift build ARN, the resource ID matches the <code>BuildId</code>\n            value. This attribute is used with fleets where <code>ComputeType</code> is \"EC2\".</p>"}))
    FleetAttributes.add_member(:script_id, Smithy::Schema::Shapes::ShapeRef.new(shape: ScriptId, location_name: 'ScriptId', traits: {"smithy.api#documentation" => "<p>A unique identifier for the Realtime script resource that is deployed on instances in this fleet.\n            This attribute is used with fleets where <code>ComputeType</code> is \"EC2\".</p>"}))
    FleetAttributes.add_member(:script_arn, Smithy::Schema::Shapes::ShapeRef.new(shape: ScriptArn, location_name: 'ScriptArn', traits: {"smithy.api#documentation" => "<p> The Amazon Resource Name (<a href=\"https://docs.aws.amazon.com/AmazonS3/latest/dev/s3-arn-format.html\">ARN</a>) associated with the GameLift script resource that is deployed on instances\n            in this fleet. In a GameLift script ARN, the resource ID matches the\n                <code>ScriptId</code> value.</p>"}))
    FleetAttributes.add_member(:server_launch_path, Smithy::Schema::Shapes::ShapeRef.new(shape: LaunchPathStringModel, location_name: 'ServerLaunchPath', traits: {"smithy.api#documentation" => "<p>\n            <b>This parameter is no longer used.</b> Server launch paths\n            are now defined using the fleet's <a href=\"https://docs.aws.amazon.com/gamelift/latest/apireference/RuntimeConfiguration.html\">RuntimeConfiguration</a>. Requests that use this parameter continue to be\n            valid.</p>"}))
    FleetAttributes.add_member(:server_launch_parameters, Smithy::Schema::Shapes::ShapeRef.new(shape: LaunchParametersStringModel, location_name: 'ServerLaunchParameters', traits: {"smithy.api#documentation" => "<p>\n            <b>This parameter is no longer used.</b> Server launch\n            parameters are now defined using the fleet's runtime configuration. Requests that use\n            this parameter continue to be valid.</p>"}))
    FleetAttributes.add_member(:log_paths, Smithy::Schema::Shapes::ShapeRef.new(shape: StringList, location_name: 'LogPaths', traits: {"smithy.api#documentation" => "<p>\n            <b>This parameter is no longer used.</b> Game session log\n            paths are now defined using the Amazon GameLift Servers server API <code>ProcessReady()</code>\n            <code>logParameters</code>. See more information in the <a href=\"https://docs.aws.amazon.com/gamelift/latest/developerguide/gamelift-sdk-server-api-ref.html#gamelift-sdk-server-api-ref-dataypes-process\">Server API Reference</a>. </p>"}))
    FleetAttributes.add_member(:new_game_session_protection_policy, Smithy::Schema::Shapes::ShapeRef.new(shape: ProtectionPolicy, location_name: 'NewGameSessionProtectionPolicy', traits: {"smithy.api#documentation" => "<p>The type of game session protection to set on all new instances that are started in\n            the fleet. This attribute is used with fleets where <code>ComputeType</code> is\n            <code>EC2</code>.</p>\n         <ul>\n            <li>\n               <p>\n                  <b>NoProtection</b> -- The game session can be\n                    terminated during a scale-down event.</p>\n            </li>\n            <li>\n               <p>\n                  <b>FullProtection</b> -- If the game session is in an\n                        <code>ACTIVE</code> status, it cannot be terminated during a scale-down\n                    event.</p>\n            </li>\n         </ul>"}))
    FleetAttributes.add_member(:operating_system, Smithy::Schema::Shapes::ShapeRef.new(shape: OperatingSystem, location_name: 'OperatingSystem', traits: {"smithy.api#documentation" => "<p>The operating system of the fleet's computing resources. A fleet's operating system is\n            determined by the OS of the build or script that is deployed on this fleet. This\n            attribute is used with fleets where <code>ComputeType</code> is\n            <code>EC2</code>.</p>\n         <note>\n            <p>Amazon Linux 2 (AL2) will reach end of support on 6/30/2025. See more details in \n            the <a href=\"http://aws.amazon.com/aws.amazon.com/amazon-linux-2/faqs/\">Amazon Linux 2 FAQs</a>. \n            For game servers\n            that are hosted on AL2 and use server SDK version 4.x for Amazon GameLift Servers, first update the\n            game server build to server SDK 5.x, and then deploy to AL2023 instances. See\n            <a href=\"https://docs.aws.amazon.com/gamelift/latest/developerguide/reference-serversdk5-migration.html\">\n                Migrate to server SDK version 5.</a>\n            </p>\n         </note>"}))
    FleetAttributes.add_member(:resource_creation_limit_policy, Smithy::Schema::Shapes::ShapeRef.new(shape: ResourceCreationLimitPolicy, location_name: 'ResourceCreationLimitPolicy'))
    FleetAttributes.add_member(:metric_groups, Smithy::Schema::Shapes::ShapeRef.new(shape: MetricGroupList, location_name: 'MetricGroups', traits: {"smithy.api#documentation" => "<p>Name of a metric group that metrics for this fleet are added to. In Amazon CloudWatch,\n            you can view aggregated metrics for fleets that are in a metric group. A fleet can be\n            included in only one metric group at a time. This attribute is used with fleets where\n            <code>ComputeType</code> is <code>EC2</code>.</p>"}))
    FleetAttributes.add_member(:stopped_actions, Smithy::Schema::Shapes::ShapeRef.new(shape: FleetActionList, location_name: 'StoppedActions', traits: {"smithy.api#documentation" => "<p>A list of fleet activity that has been suspended using <a href=\"https://docs.aws.amazon.com/gamelift/latest/apireference/API_StopFleetActions.html\">StopFleetActions</a>. This includes fleet auto-scaling. This attribute is used\n            with fleets where <code>ComputeType</code> is <code>EC2</code>.</p>"}))
    FleetAttributes.add_member(:instance_role_arn, Smithy::Schema::Shapes::ShapeRef.new(shape: NonEmptyString, location_name: 'InstanceRoleArn', traits: {"smithy.api#documentation" => "<p>A unique identifier for an IAM role that manages access to your Amazon Web Services services. \n        With an instance role ARN set, any application that runs on an instance in this fleet can assume the role, \n        including install scripts, server processes, and daemons (background processes). Create a role or look up a role's \n        ARN by using the <a href=\"https://console.aws.amazon.com/iam/\">IAM dashboard</a> in the Amazon Web Services Management Console.\n        Learn more about using on-box credentials for your game servers at \n        <a href=\"https://docs.aws.amazon.com/gamelift/latest/developerguide/gamelift-sdk-server-resources.html\">\n        Access external resources from a game server</a>. This attribute is used with fleets where <code>ComputeType</code> is\n            <code>EC2</code>.</p>"}))
    FleetAttributes.add_member(:certificate_configuration, Smithy::Schema::Shapes::ShapeRef.new(shape: CertificateConfiguration, location_name: 'CertificateConfiguration', traits: {"smithy.api#documentation" => "<p>Determines whether a TLS/SSL certificate is generated for a fleet. This feature must be enabled when creating the fleet. \n            All instances in a fleet share the same certificate.</p>"}))
    FleetAttributes.add_member(:compute_type, Smithy::Schema::Shapes::ShapeRef.new(shape: ComputeType, location_name: 'ComputeType', traits: {"smithy.api#documentation" => "<p>The type of compute resource used to host your game servers. You can use your own\n            compute resources with Amazon GameLift Servers Anywhere or use Amazon EC2 instances with managed\n            Amazon GameLift Servers.</p>"}))
    FleetAttributes.add_member(:anywhere_configuration, Smithy::Schema::Shapes::ShapeRef.new(shape: AnywhereConfiguration, location_name: 'AnywhereConfiguration', traits: {"smithy.api#documentation" => "<p>A set of attributes that are specific to an Anywhere fleet.</p>"}))
    FleetAttributes.add_member(:instance_role_credentials_provider, Smithy::Schema::Shapes::ShapeRef.new(shape: InstanceRoleCredentialsProvider, location_name: 'InstanceRoleCredentialsProvider', traits: {"smithy.api#documentation" => "<p>Indicates that fleet instances maintain a shared credentials file for the IAM role defined in <code>InstanceRoleArn</code>. Shared credentials allow\n            applications that are deployed with the game server executable to communicate with other\n            Amazon Web Services resources. This property is used only when the game server is integrated with the\n            server SDK version 5.x. For more information about using shared credentials, see <a href=\"https://docs.aws.amazon.com/gamelift/latest/developerguide/gamelift-sdk-server-resources.html\"> Communicate\n                with other Amazon Web Services resources from your fleets</a>. This attribute is used with\n                fleets where <code>ComputeType</code> is <code>EC2</code>.</p>"}))
