    FleetCapacity.add_member(:instance_type, Smithy::Schema::Shapes::ShapeRef.new(shape: EC2InstanceType, location_name: 'InstanceType', traits: {"smithy.api#documentation" => "<p>The Amazon EC2 instance type that is used for instances in a fleet. Instance type\n            determines the computing resources in use, including CPU, memory, storage, and\n            networking capacity. See <a href=\"http://aws.amazon.com/ec2/instance-types/\">Amazon Elastic Compute Cloud\n                Instance Types</a> for detailed descriptions.</p>"}))
    FleetCapacity.add_member(:instance_counts, Smithy::Schema::Shapes::ShapeRef.new(shape: EC2InstanceCounts, location_name: 'InstanceCounts', traits: {"smithy.api#documentation" => "<p>The current number of instances in the fleet, listed by instance status. Counts for pending and\n            terminating instances might be non-zero if the fleet is adjusting to a scaling event\n            or if access to resources is temporarily affected.</p>"}))
    FleetCapacity.add_member(:location, Smithy::Schema::Shapes::ShapeRef.new(shape: LocationStringModel, location_name: 'Location', traits: {"smithy.api#documentation" => "<p>The fleet location for the instance count information, expressed as an Amazon Web Services Region\n            code, such as <code>us-west-2</code>. </p>"}))
