    FleetDeployment.add_member(:deployment_status, Smithy::Schema::Shapes::ShapeRef.new(shape: DeploymentStatus, location_name: 'DeploymentStatus', traits: {"smithy.api#documentation" => "<p>The status of fleet deployment activity in the location. </p>\n         <ul>\n            <li>\n               <p>\n                  <code>IN_PROGRESS</code> -- The deployment is in progress.</p>\n            </li>\n            <li>\n               <p>\n                  <code>IMPAIRED</code> -- The deployment failed and the fleet has some impaired\n                    containers. </p>\n            </li>\n            <li>\n               <p>\n                  <code>COMPLETE</code> -- The deployment has completed successfully.</p>\n            </li>\n            <li>\n               <p>\n                  <code>ROLLBACK_IN_PROGRESS</code> -- The deployment failed and rollback has\n                    been initiated.</p>\n            </li>\n            <li>\n               <p>\n                  <code>ROLLBACK_IN_COMPLETE</code> -- The deployment failed and rollback has\n                    been completed.</p>\n            </li>\n            <li>\n               <p>\n                  <code>CANCELLED</code> -- The deployment was cancelled.</p>\n            </li>\n         </ul>"}))
    FleetDeployment.add_member(:deployment_configuration, Smithy::Schema::Shapes::ShapeRef.new(shape: DeploymentConfiguration, location_name: 'DeploymentConfiguration', traits: {"smithy.api#documentation" => "<p>Instructions for how to deploy updates to a container fleet and what actions to take\n            if the deployment fails.</p>"}))
