    FleetUtilization.add_member(:fleet_arn, Smithy::Schema::Shapes::ShapeRef.new(shape: FleetArn, location_name: 'FleetArn', traits: {"smithy.api#documentation" => "<p>The Amazon Resource Name (<a href=\"https://docs.aws.amazon.com/AmazonS3/latest/dev/s3-arn-format.html\">ARN</a>) that is assigned to a Amazon GameLift Servers fleet resource and uniquely identifies it. ARNs are unique across all Regions. Format is <code>arn:aws:gamelift:<region>::fleet/fleet-a1234567-b8c9-0d1e-2fa3-b45c6d7e8912</code>.</p>"}))
    FleetUtilization.add_member(:active_server_process_count, Smithy::Schema::Shapes::ShapeRef.new(shape: WholeNumber, location_name: 'ActiveServerProcessCount', traits: {"smithy.api#documentation" => "<p>The number of server processes in <code>ACTIVE</code> status that are currently\n            running across all instances in the fleet location. </p>"}))
    FleetUtilization.add_member(:active_game_session_count, Smithy::Schema::Shapes::ShapeRef.new(shape: WholeNumber, location_name: 'ActiveGameSessionCount', traits: {"smithy.api#documentation" => "<p>The number of active game sessions that are currently being hosted across all\n            instances in the fleet location.</p>"}))
