    GameServer.add_member(:game_server_id, Smithy::Schema::Shapes::ShapeRef.new(shape: GameServerId, location_name: 'GameServerId', traits: {"smithy.api#documentation" => "<p>A custom string that uniquely identifies the game server. Game server IDs are developer-defined and are unique across all game\n            server groups in an Amazon Web Services account.</p>"}))
    GameServer.add_member(:instance_id, Smithy::Schema::Shapes::ShapeRef.new(shape: GameServerInstanceId, location_name: 'InstanceId', traits: {"smithy.api#documentation" => "<p>The unique identifier for the instance where the game server is running. This ID is\n            available in the instance metadata. EC2 instance IDs \n            use a 17-character format, for example: <code>i-1234567890abcdef0</code>.</p>"}))
    GameServer.add_member(:connection_info, Smithy::Schema::Shapes::ShapeRef.new(shape: GameServerConnectionInfo, location_name: 'ConnectionInfo', traits: {"smithy.api#documentation" => "<p>The port and IP address that must be used to establish a client connection to the game\n            server.</p>"}))
    GameServer.add_member(:game_server_data, Smithy::Schema::Shapes::ShapeRef.new(shape: GameServerData, location_name: 'GameServerData', traits: {"smithy.api#documentation" => "<p>A set of custom game server properties, formatted as a single string value. This data \n            is passed to a game client or service when it requests information on game servers.</p>"}))
    GameServer.add_member(:claim_status, Smithy::Schema::Shapes::ShapeRef.new(shape: GameServerClaimStatus, location_name: 'ClaimStatus', traits: {"smithy.api#documentation" => "<p>Indicates when an available game server has been reserved for gameplay but has not yet\n            started hosting a game. Once it is claimed, the game server remains in\n                <code>CLAIMED</code> status for a maximum of one minute. During this time, game\n            clients connect to the game server to start the game and trigger the game server to\n            update its utilization status. After one minute, the game server claim status reverts to\n            null.</p>"}))
    GameServer.add_member(:utilization_status, Smithy::Schema::Shapes::ShapeRef.new(shape: GameServerUtilizationStatus, location_name: 'UtilizationStatus', traits: {"smithy.api#documentation" => "<p>Indicates whether the game server is currently available for new games or is busy.\n            Possible statuses include:</p>\n         <ul>\n            <li>\n               <p>\n                  <code>AVAILABLE</code> - The game server is available to be claimed. A game\n                    server that has been claimed remains in this status until it reports game\n                    hosting activity. </p>\n            </li>\n            <li>\n               <p>\n                  <code>UTILIZED</code> - The game server is currently hosting a game session\n                    with players. </p>\n            </li>\n         </ul>"}))
    GameServer.add_member(:registration_time, Smithy::Schema::Shapes::ShapeRef.new(shape: Timestamp, location_name: 'RegistrationTime', traits: {"smithy.api#documentation" => "<p>Timestamp that indicates when the game server registered. The format is a number expressed in Unix\n            time as milliseconds (for example <code>\"1469498468.057\"</code>).</p>"}))
    GameServer.add_member(:last_claim_time, Smithy::Schema::Shapes::ShapeRef.new(shape: Timestamp, location_name: 'LastClaimTime', traits: {"smithy.api#documentation" => "<p>Timestamp that indicates the last time the game server was claimed. The format is a\n            number expressed in Unix time as milliseconds (for example\n            <code>\"1469498468.057\"</code>). This value is used to calculate when a claimed game\n            server's status should revert to null.</p>"}))
    GameServer.add_member(:last_health_check_time, Smithy::Schema::Shapes::ShapeRef.new(shape: Timestamp, location_name: 'LastHealthCheckTime', traits: {"smithy.api#documentation" => "<p>Timestamp that indicates the last time the game server was updated with health status.\n            The format is a number expressed in Unix time as milliseconds (for example\n                <code>\"1469498468.057\"</code>). After game server registration, this property is\n            only changed when a game server update specifies a health check value.</p>"}))
