    GameServerContainerDefinition.add_member(:image_uri, Smithy::Schema::Shapes::ShapeRef.new(shape: ImageUriString, location_name: 'ImageUri', traits: {"smithy.api#documentation" => "<p>The URI to the image that Amazon GameLift Servers uses when deploying this container to a container fleet.\n      For a more specific identifier, see <code>ResolvedImageDigest</code>. </p>"}))
    GameServerContainerDefinition.add_member(:port_configuration, Smithy::Schema::Shapes::ShapeRef.new(shape: ContainerPortConfiguration, location_name: 'PortConfiguration', traits: {"smithy.api#documentation" => "<p>The set of ports that are available to bind to processes in the container. For example, a\n      game server process requires a container port to allow game clients to connect to it.\n      Container ports aren't directly accessed by inbound traffic. Amazon GameLift Servers maps these container\n      ports to externally accessible connection ports, which are assigned as needed from the\n      container fleet's <code>ConnectionPortRange</code>. </p>"}))
    GameServerContainerDefinition.add_member(:resolved_image_digest, Smithy::Schema::Shapes::ShapeRef.new(shape: Sha256, location_name: 'ResolvedImageDigest', traits: {"smithy.api#documentation" => "<p>A unique and immutable identifier for the container image. The digest is a SHA 256 hash of\n      the container image manifest. </p>"}))
