    GameServerContainerDefinitionInput.add_member(:container_name, Smithy::Schema::Shapes::ShapeRef.new(shape: NonZeroAnd128MaxAsciiString, location_name: 'ContainerName', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>A string that uniquely identifies the container definition within a container\n      group.</p>", "smithy.api#required" => {}}))
    GameServerContainerDefinitionInput.add_member(:depends_on, Smithy::Schema::Shapes::ShapeRef.new(shape: ContainerDependencyList, location_name: 'DependsOn', traits: {"smithy.api#documentation" => "<p>Establishes dependencies between this container and the status of other containers in the\n      same container group. A container can have dependencies on multiple different containers. </p>\n         <p>You can use dependencies to establish a startup/shutdown sequence across the container\n      group. For example, you might specify that <i>ContainerB</i> has a\n        <code>START</code> dependency on <i>ContainerA</i>. This dependency means that\n        <i>ContainerB</i> can't start until after <i>ContainerA</i> has\n      started. This dependency is reversed on shutdown, which means that\n        <i>ContainerB</i> must shut down before <i>ContainerA</i> can\n      shut down. </p>"}))
    GameServerContainerDefinitionInput.add_member(:mount_points, Smithy::Schema::Shapes::ShapeRef.new(shape: ContainerMountPointList, location_name: 'MountPoints', traits: {"smithy.api#documentation" => "<p>A mount point that binds a path inside the container to a file or directory on the host\n      system and lets it access the file or directory.</p>"}))
    GameServerContainerDefinitionInput.add_member(:environment_override, Smithy::Schema::Shapes::ShapeRef.new(shape: ContainerEnvironmentList, location_name: 'EnvironmentOverride', traits: {"smithy.api#documentation" => "<p>A set of environment variables to pass to the container on startup. See the <a href=\"https://docs.aws.amazon.com/AmazonECS/latest/APIReference/API_ContainerDefinition.html#ECS-Type-ContainerDefinition-environment\">ContainerDefinition::environment</a> parameter in the <i>Amazon Elastic Container Service API\n        Reference</i>. </p>"}))
    GameServerContainerDefinitionInput.add_member(:image_uri, Smithy::Schema::Shapes::ShapeRef.new(shape: ImageUriString, location_name: 'ImageUri', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>The location of the container image to deploy to a container fleet. Provide an image in an\n      Amazon Elastic Container Registry public or private repository. The repository must be in the same Amazon Web Services account and\n      Amazon Web Services Region where you're creating the container group definition. For limits on image size,\n      see <a href=\"https://docs.aws.amazon.com/general/latest/gr/gamelift.html\">Amazon GameLift Servers endpoints and\n        quotas</a>. You can use any of the following image URI formats: </p>\n         <ul>\n            <li>\n               <p>Image ID only: <code>[AWS account].dkr.ecr.[AWS region].amazonaws.com/[repository\n          ID]</code>\n               </p>\n            </li>\n            <li>\n               <p>Image ID and digest: <code>[AWS account].dkr.ecr.[AWS\n          region].amazonaws.com/[repository ID]@[digest]</code>\n               </p>\n            </li>\n            <li>\n               <p>Image ID and tag: <code>[AWS account].dkr.ecr.[AWS region].amazonaws.com/[repository\n          ID]:[tag]</code>\n               </p>\n            </li>\n         </ul>", "smithy.api#required" => {}}))
    GameServerContainerDefinitionInput.add_member(:port_configuration, Smithy::Schema::Shapes::ShapeRef.new(shape: ContainerPortConfiguration, location_name: 'PortConfiguration', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>A set of ports that Amazon GameLift Servers can assign to processes in a container. The container port\n      configuration must have enough ports for each container process that accepts inbound traffic\n      connections. For example, a game server process requires a container port to allow game\n      clients to connect to it. A container port configuration can have can have one or more\n      container port ranges. Each range specifies starting and ending values as well as the\n      supported network protocol.</p>\n         <p>Container ports aren't directly accessed by inbound traffic. Amazon GameLift Servers maps each container\n      port to an externally accessible connection port (see the container fleet property\n        <code>ConnectionPortRange</code>). </p>", "smithy.api#required" => {}}))
    GameServerContainerDefinitionInput.add_member(:server_sdk_version, Smithy::Schema::Shapes::ShapeRef.new(shape: ServerSdkVersion, location_name: 'ServerSdkVersion', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>The Amazon GameLift Servers server SDK version that the game server is integrated with. Only game servers\n      using 5.2.0 or higher are compatible with container fleets.</p>", "smithy.api#required" => {}}))
