    GameServerContainerGroupCounts.add_member(:active, Smithy::Schema::Shapes::ShapeRef.new(shape: WholeNumber, location_name: 'ACTIVE', traits: {"smithy.api#documentation" => "<p>\n            The number of container groups that have active game sessions.\n        </p>"}))
