    GameServerGroup.add_member(:game_server_group_name, Smithy::Schema::Shapes::ShapeRef.new(shape: GameServerGroupName, location_name: 'GameServerGroupName', traits: {"smithy.api#documentation" => "<p>A developer-defined identifier for the game server group. The name is unique for each\n            Region in each Amazon Web Services account.</p>"}))
    GameServerGroup.add_member(:game_server_group_arn, Smithy::Schema::Shapes::ShapeRef.new(shape: GameServerGroupArn, location_name: 'GameServerGroupArn', traits: {"smithy.api#documentation" => "<p>A generated unique ID for the game server group.</p>"}))
    GameServerGroup.add_member(:role_arn, Smithy::Schema::Shapes::ShapeRef.new(shape: IamRoleArn, location_name: 'RoleArn', traits: {"smithy.api#documentation" => "<p>The Amazon Resource Name (<a href=\"https://docs.aws.amazon.com/AmazonS3/latest/dev/s3-arn-format.html\">ARN</a>) for an IAM role that\n            allows Amazon GameLift Servers to access your Amazon EC2 Auto Scaling groups.</p>"}))
    GameServerGroup.add_member(:instance_definitions, Smithy::Schema::Shapes::ShapeRef.new(shape: InstanceDefinitions, location_name: 'InstanceDefinitions', traits: {"smithy.api#documentation" => "<p>The set of Amazon EC2 instance types that Amazon GameLift Servers FleetIQ can use when balancing and automatically\n            scaling instances in the corresponding Auto Scaling group. </p>"}))
    GameServerGroup.add_member(:balancing_strategy, Smithy::Schema::Shapes::ShapeRef.new(shape: BalancingStrategy, location_name: 'BalancingStrategy', traits: {"smithy.api#documentation" => "<p>Indicates how Amazon GameLift Servers FleetIQ balances the use of Spot Instances and On-Demand Instances in the\n            game server group. Method options include the following:</p>\n         <ul>\n            <li>\n               <p>\n                  <code>SPOT_ONLY</code> - Only Spot Instances are used in the game server group. If Spot\n                    Instances are unavailable or not viable for game hosting, the game server group\n                    provides no hosting capacity until Spot Instances can again be used. Until then,\n                    no new instances are started, and the existing nonviable Spot Instances are\n                    terminated (after current gameplay ends) and are not replaced.</p>\n            </li>\n            <li>\n               <p>\n                  <code>SPOT_PREFERRED</code> - (default value) Spot Instances are used whenever available in\n                    the game server group. If Spot Instances are unavailable, the game server group\n                    continues to provide hosting capacity by falling back to On-Demand Instances.\n                    Existing nonviable Spot Instances are terminated (after current gameplay ends)\n                    and are replaced with new On-Demand Instances.</p>\n            </li>\n            <li>\n               <p>\n                  <code>ON_DEMAND_ONLY</code> - Only On-Demand Instances are used in the game\n                    server group. No Spot Instances are used, even when available, while this\n                    balancing strategy is in force.</p>\n            </li>\n         </ul>"}))
    GameServerGroup.add_member(:game_server_protection_policy, Smithy::Schema::Shapes::ShapeRef.new(shape: GameServerProtectionPolicy, location_name: 'GameServerProtectionPolicy', traits: {"smithy.api#documentation" => "<p>A flag that indicates whether instances in the game server group are protected \n            from early termination. Unprotected instances that have active game servers running might \n            be terminated during a scale-down event, causing players to be dropped from the game. \n            Protected instances cannot be terminated while there are active game servers running except \n            in the event of a forced game server group deletion (see ). An exception to this is with Spot \n            Instances, which can be terminated by Amazon Web Services regardless of protection status. </p>"}))
    GameServerGroup.add_member(:auto_scaling_group_arn, Smithy::Schema::Shapes::ShapeRef.new(shape: AutoScalingGroupArn, location_name: 'AutoScalingGroupArn', traits: {"smithy.api#documentation" => "<p>A generated unique ID for the Amazon EC2 Auto Scaling group that is associated with this\n            game server group.</p>"}))
    GameServerGroup.add_member(:status, Smithy::Schema::Shapes::ShapeRef.new(shape: GameServerGroupStatus, location_name: 'Status', traits: {"smithy.api#documentation" => "<p>The current status of the game server group. Possible statuses include:</p>\n         <ul>\n            <li>\n               <p>\n                  <code>NEW</code> - Amazon GameLift Servers FleetIQ has validated the <code>CreateGameServerGroup()</code>\n                    request. </p>\n            </li>\n            <li>\n               <p>\n                  <code>ACTIVATING</code> - Amazon GameLift Servers FleetIQ is setting up a game server group, which\n                    includes creating an Auto Scaling group in your Amazon Web Services account. </p>\n            </li>\n            <li>\n               <p>\n                  <code>ACTIVE</code> - The game server group has been successfully created.\n                </p>\n            </li>\n            <li>\n               <p>\n                  <code>DELETE_SCHEDULED</code> - A request to delete the game server group has\n                    been received. </p>\n            </li>\n            <li>\n               <p>\n                  <code>DELETING</code> - Amazon GameLift Servers FleetIQ has received a valid\n                        <code>DeleteGameServerGroup()</code> request and is processing it. Amazon GameLift Servers FleetIQ\n                    must first complete and release hosts before it deletes the Auto Scaling group\n                    and the game server group. </p>\n            </li>\n            <li>\n               <p>\n                  <code>DELETED</code> - The game server group has been successfully deleted.\n                </p>\n            </li>\n            <li>\n               <p>\n                  <code>ERROR</code> - The asynchronous processes of activating or deleting a\n                    game server group has failed, resulting in an error state.</p>\n            </li>\n         </ul>"}))
    GameServerGroup.add_member(:status_reason, Smithy::Schema::Shapes::ShapeRef.new(shape: NonZeroAndMaxString, location_name: 'StatusReason', traits: {"smithy.api#documentation" => "<p>Additional information about the current game server group status. This information\n            might provide additional insight on groups that are in <code>ERROR</code> status.</p>"}))
    GameServerGroup.add_member(:suspended_actions, Smithy::Schema::Shapes::ShapeRef.new(shape: GameServerGroupActions, location_name: 'SuspendedActions', traits: {"smithy.api#documentation" => "<p>A list of activities that are currently suspended for this game server group. If this\n            property is empty, all activities are occurring.</p>"}))
    GameServerGroup.add_member(:creation_time, Smithy::Schema::Shapes::ShapeRef.new(shape: Timestamp, location_name: 'CreationTime', traits: {"smithy.api#documentation" => "<p>A time stamp indicating when this data object was created. Format is a number expressed in Unix time as milliseconds (for example <code>\"1469498468.057\"</code>).</p>"}))
