    GameServerGroupAutoScalingPolicy.add_member(:estimated_instance_warmup, Smithy::Schema::Shapes::ShapeRef.new(shape: PositiveInteger, location_name: 'EstimatedInstanceWarmup', traits: {"smithy.api#documentation" => "<p>Length of time, in seconds, it takes for a new instance to start new game server\n            processes and register with Amazon GameLift Servers FleetIQ. Specifying a warm-up time can be useful, particularly\n            with game servers that take a long time to start up, because it avoids prematurely\n            starting new instances. </p>"}))
    GameServerGroupAutoScalingPolicy.add_member(:target_tracking_configuration, Smithy::Schema::Shapes::ShapeRef.new(shape: TargetTrackingConfiguration, location_name: 'TargetTrackingConfiguration', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>Settings for a target-based scaling policy applied to Auto Scaling group. These\n            settings are used to create a target-based policy that tracks the Amazon GameLift Servers FleetIQ metric\n                <code>\"PercentUtilizedGameServers\"</code> and specifies a target value for the\n            metric. As player usage changes, the policy triggers to adjust the game server group\n            capacity so that the metric returns to the target value. </p>", "smithy.api#required" => {}}))
