    GameSession.add_member(:name, Smithy::Schema::Shapes::ShapeRef.new(shape: NonZeroAndMaxString, location_name: 'Name', traits: {"smithy.api#documentation" => "<p>A descriptive label that is associated with a game session. Session names do not need to be unique.</p>"}))
