    GameSession.add_member(:current_player_session_count, Smithy::Schema::Shapes::ShapeRef.new(shape: WholeNumber, location_name: 'CurrentPlayerSessionCount', traits: {"smithy.api#documentation" => "<p>Number of players currently in the game session.</p>"}))
    GameSession.add_member(:maximum_player_session_count, Smithy::Schema::Shapes::ShapeRef.new(shape: WholeNumber, location_name: 'MaximumPlayerSessionCount', traits: {"smithy.api#documentation" => "<p>The maximum number of players that can be connected simultaneously to the game session.</p>"}))
    GameSession.add_member(:status, Smithy::Schema::Shapes::ShapeRef.new(shape: GameSessionStatus, location_name: 'Status', traits: {"smithy.api#documentation" => "<p>Current status of the game session. A game session must have an <code>ACTIVE</code>\n            status to have player sessions.</p>"}))
    GameSession.add_member(:status_reason, Smithy::Schema::Shapes::ShapeRef.new(shape: GameSessionStatusReason, location_name: 'StatusReason', traits: {"smithy.api#documentation" => "<p>Provides additional information about game session status. </p>\n         <ul>\n            <li>\n               <p>\n                  <code>INTERRUPTED</code> -- The game session was hosted on an EC2 Spot instance that was\n                    reclaimed, causing the active game session to be stopped.</p>\n            </li>\n            <li>\n               <p>\n                  <code>TRIGGERED_ON_PROCESS_TERMINATE</code> – The game session was stopped by calling\n                        <code>TerminateGameSession</code> with the termination mode\n                        <code>TRIGGER_ON_PROCESS_TERMINATE</code>. </p>\n            </li>\n            <li>\n               <p>\n                  <code>FORCE_TERMINATED</code> – The game session was stopped by calling\n                        <code>TerminateGameSession</code> with the termination mode\n                        <code>FORCE_TERMINATE</code>. </p>\n            </li>\n         </ul>\n         <p></p>"}))
    GameSession.add_member(:game_properties, Smithy::Schema::Shapes::ShapeRef.new(shape: GamePropertyList, location_name: 'GameProperties', traits: {"smithy.api#documentation" => "<p>A set of key-value pairs that can store custom data in a game session.\n  For example: <code>{\"Key\": \"difficulty\", \"Value\": \"novice\"}</code>.</p>"}))
    GameSession.add_member(:ip_address, Smithy::Schema::Shapes::ShapeRef.new(shape: IpAddress, location_name: 'IpAddress', traits: {"smithy.api#documentation" => "<p>The IP address of the game session. To connect to a Amazon GameLift Servers game server, an app needs both the IP address and port number.</p>"}))
    GameSession.add_member(:dns_name, Smithy::Schema::Shapes::ShapeRef.new(shape: DnsName, location_name: 'DnsName', traits: {"smithy.api#documentation" => "<p>The DNS identifier assigned to the instance that is running the game session. Values have\n            the following format:</p>\n         <ul>\n            <li>\n               <p>TLS-enabled fleets: <code><unique identifier>.<region identifier>.amazongamelift.com</code>.</p>\n            </li>\n            <li>\n               <p>Non-TLS-enabled fleets: <code>ec2-<unique identifier>.compute.amazonaws.com</code>. (See\n            <a href=\"https://docs.aws.amazon.com/AWSEC2/latest/UserGuide/using-instance-addressing.html#concepts-public-addresses\">Amazon EC2 Instance IP Addressing</a>.)</p>\n            </li>\n         </ul>\n         <p>When connecting to a game session that is running on a TLS-enabled fleet, you must use the DNS name, not the IP address.</p>"}))
    GameSession.add_member(:port, Smithy::Schema::Shapes::ShapeRef.new(shape: PortNumber, location_name: 'Port', traits: {"smithy.api#documentation" => "<p>The port number for the game session. To connect to a Amazon GameLift Servers game server, an app needs both the IP address and port number.</p>"}))
    GameSession.add_member(:player_session_creation_policy, Smithy::Schema::Shapes::ShapeRef.new(shape: PlayerSessionCreationPolicy, location_name: 'PlayerSessionCreationPolicy', traits: {"smithy.api#documentation" => "<p>Indicates whether the game session is accepting new players.</p>"}))
    GameSession.add_member(:creator_id, Smithy::Schema::Shapes::ShapeRef.new(shape: NonZeroAndMaxString, location_name: 'CreatorId', traits: {"smithy.api#documentation" => "<p>A unique identifier for a player. This ID is used to enforce a resource protection policy (if one exists),\n            that limits the number of game sessions a player can create.</p>"}))
    GameSession.add_member(:game_session_data, Smithy::Schema::Shapes::ShapeRef.new(shape: LargeGameSessionData, location_name: 'GameSessionData', traits: {"smithy.api#documentation" => "<p>A set of custom game session properties, formatted as a single string value. This data is passed to a game server process with a request to start a new game session. For more information, see <a href=\"https://docs.aws.amazon.com/gamelift/latest/developerguide/gamelift-sdk-server-api.html#gamelift-sdk-server-startsession\">Start a game session</a>.</p>"}))
