    MatchmakingConfiguration.add_member(:game_session_queue_arns, Smithy::Schema::Shapes::ShapeRef.new(shape: QueueArnsList, location_name: 'GameSessionQueueArns', traits: {"smithy.api#documentation" => "<p>The Amazon Resource Name (<a href=\"https://docs.aws.amazon.com/AmazonS3/latest/dev/s3-arn-format.html\">ARN</a>) that is assigned to a Amazon GameLift Servers game session queue resource and uniquely identifies it. ARNs are unique across all Regions. Format is <code>arn:aws:gamelift:<region>::gamesessionqueue/<queue name></code>. Queues can be located in any Region. Queues are used to start new\n            Amazon GameLift Servers-hosted game sessions for matches that are created with this matchmaking\n            configuration. This property is not set when <code>FlexMatchMode</code> is set to\n                <code>STANDALONE</code>.</p>"}))
    MatchmakingConfiguration.add_member(:request_timeout_seconds, Smithy::Schema::Shapes::ShapeRef.new(shape: MatchmakingRequestTimeoutInteger, location_name: 'RequestTimeoutSeconds', traits: {"smithy.api#documentation" => "<p>The maximum duration, in seconds, that a matchmaking ticket can remain in process\n            before timing out. Requests that fail due to timing out can be resubmitted as\n            needed.</p>"}))
    MatchmakingConfiguration.add_member(:acceptance_timeout_seconds, Smithy::Schema::Shapes::ShapeRef.new(shape: MatchmakingAcceptanceTimeoutInteger, location_name: 'AcceptanceTimeoutSeconds', traits: {"smithy.api#documentation" => "<p>The length of time (in seconds) to wait for players to accept a proposed match, if\n            acceptance is required. If any player rejects the match or fails to accept before the\n            timeout, the ticket continues to look for an acceptable match.</p>"}))
    MatchmakingConfiguration.add_member(:acceptance_required, Smithy::Schema::Shapes::ShapeRef.new(shape: BooleanModel, location_name: 'AcceptanceRequired', traits: {"smithy.api#documentation" => "<p>A flag that indicates whether a match that was created with this configuration must be\n            accepted by the matched players. To require acceptance, set to TRUE. When this option is\n            enabled, matchmaking tickets use the status <code>REQUIRES_ACCEPTANCE</code> to indicate\n            when a completed potential match is waiting for player acceptance.</p>"}))
    MatchmakingConfiguration.add_member(:rule_set_name, Smithy::Schema::Shapes::ShapeRef.new(shape: MatchmakingIdStringModel, location_name: 'RuleSetName', traits: {"smithy.api#documentation" => "<p>A unique identifier for the matchmaking rule set to use with this configuration. A matchmaking configuration can only use rule\n            sets that are defined in the same Region.</p>"}))
    MatchmakingConfiguration.add_member(:rule_set_arn, Smithy::Schema::Shapes::ShapeRef.new(shape: MatchmakingRuleSetArn, location_name: 'RuleSetArn', traits: {"smithy.api#documentation" => "<p>The Amazon Resource Name (<a href=\"https://docs.aws.amazon.com/AmazonS3/latest/dev/s3-arn-format.html\">ARN</a>) associated with the GameLift matchmaking rule set resource that this\n            configuration uses.</p>"}))
    MatchmakingConfiguration.add_member(:notification_target, Smithy::Schema::Shapes::ShapeRef.new(shape: SnsArnStringModel, location_name: 'NotificationTarget', traits: {"smithy.api#documentation" => "<p>An SNS topic ARN that is set up to receive matchmaking notifications.</p>"}))
    MatchmakingConfiguration.add_member(:additional_player_count, Smithy::Schema::Shapes::ShapeRef.new(shape: WholeNumber, location_name: 'AdditionalPlayerCount', traits: {"smithy.api#documentation" => "<p>The number of player slots in a match to keep open for future players. For example, if the configuration's rule set specifies \n            a match for a single 12-person team, and the additional player count is set to 2, only 10 players are selected for the match. This parameter is not used when <code>FlexMatchMode</code> is set to\n                <code>STANDALONE</code>.</p>"}))
    MatchmakingConfiguration.add_member(:custom_event_data, Smithy::Schema::Shapes::ShapeRef.new(shape: CustomEventData, location_name: 'CustomEventData', traits: {"smithy.api#documentation" => "<p>Information to attach to all events related to the matchmaking configuration. </p>"}))
    MatchmakingConfiguration.add_member(:creation_time, Smithy::Schema::Shapes::ShapeRef.new(shape: Timestamp, location_name: 'CreationTime', traits: {"smithy.api#documentation" => "<p>A time stamp indicating when this data object was created. Format is a number expressed in Unix time as milliseconds (for example <code>\"1469498468.057\"</code>).</p>"}))
    MatchmakingConfiguration.add_member(:game_properties, Smithy::Schema::Shapes::ShapeRef.new(shape: GamePropertyList, location_name: 'GameProperties', traits: {"smithy.api#documentation" => "<p>A set of key-value pairs that can store custom data in a game session.\n  For example: <code>{\"Key\": \"difficulty\", \"Value\": \"novice\"}</code>. This information is added to the new <code>GameSession</code> object that is\n            created for a successful match. This parameter is not used when\n                <code>FlexMatchMode</code> is set to <code>STANDALONE</code>.</p>"}))
    MatchmakingConfiguration.add_member(:game_session_data, Smithy::Schema::Shapes::ShapeRef.new(shape: GameSessionData, location_name: 'GameSessionData', traits: {"smithy.api#documentation" => "<p>A set of custom game session properties, formatted as a single string value. This data is passed to a game server process with a request to start a new game session. For more information, see <a href=\"https://docs.aws.amazon.com/gamelift/latest/developerguide/gamelift-sdk-server-api.html#gamelift-sdk-server-startsession\">Start a game session</a>. This information is added to the new <code>GameSession</code> object that is\n            created for a successful match. This parameter is not used when\n                <code>FlexMatchMode</code> is set to <code>STANDALONE</code>.</p>"}))
    MatchmakingConfiguration.add_member(:backfill_mode, Smithy::Schema::Shapes::ShapeRef.new(shape: BackfillMode, location_name: 'BackfillMode', traits: {"smithy.api#documentation" => "<p>The method used to backfill game sessions created with this matchmaking configuration.\n            MANUAL indicates that the game makes backfill requests or does not use the match\n            backfill feature. AUTOMATIC indicates that GameLift creates backfill requests whenever a\n            game session has one or more open slots. Learn more about manual and automatic backfill\n            in <a href=\"https://docs.aws.amazon.com/gamelift/latest/flexmatchguide/match-backfill.html\">Backfill existing games with FlexMatch</a>. Automatic backfill is not available\n            when <code>FlexMatchMode</code> is set to <code>STANDALONE</code>.</p>"}))
    MatchmakingConfiguration.add_member(:flex_match_mode, Smithy::Schema::Shapes::ShapeRef.new(shape: FlexMatchMode, location_name: 'FlexMatchMode', traits: {"smithy.api#documentation" => "<p>Indicates whether this matchmaking configuration is being used with Amazon GameLift Servers hosting or\n            as a standalone matchmaking solution. </p>\n         <ul>\n            <li>\n               <p>\n                  <b>STANDALONE</b> - FlexMatch forms matches and\n                    returns match information, including players and team assignments, in a <a href=\"https://docs.aws.amazon.com/gamelift/latest/flexmatchguide/match-events.html#match-events-matchmakingsucceeded\"> MatchmakingSucceeded</a> event.</p>\n            </li>\n            <li>\n               <p>\n                  <b>WITH_QUEUE</b> - FlexMatch forms matches and uses\n                    the specified Amazon GameLift Servers queue to start a game session for the match. </p>\n            </li>\n         </ul>"}))
