    PlayerSession.add_member(:status, Smithy::Schema::Shapes::ShapeRef.new(shape: PlayerSessionStatus, location_name: 'Status', traits: {"smithy.api#documentation" => "<p>Current status of the player session.</p>\n         <p>Possible player session statuses include the following:</p>\n         <ul>\n            <li>\n               <p>\n                  <b>RESERVED</b> -- The player session request has been\n                    received, but the player has not yet connected to the server process and/or been\n                    validated. </p>\n            </li>\n            <li>\n               <p>\n                  <b>ACTIVE</b> -- The player has been validated by the\n                    server process and is currently connected.</p>\n            </li>\n            <li>\n               <p>\n                  <b>COMPLETED</b> -- The player connection has been\n                    dropped.</p>\n            </li>\n            <li>\n               <p>\n                  <b>TIMEDOUT</b> -- A player session request was\n                    received, but the player did not connect and/or was not validated within the\n                    timeout limit (60 seconds).</p>\n            </li>\n         </ul>"}))
    PlayerSession.add_member(:ip_address, Smithy::Schema::Shapes::ShapeRef.new(shape: IpAddress, location_name: 'IpAddress', traits: {"smithy.api#documentation" => "<p>The IP address of the game session. To connect to a Amazon GameLift Servers game server, an app needs both the IP address and port number.</p>"}))
    PlayerSession.add_member(:dns_name, Smithy::Schema::Shapes::ShapeRef.new(shape: DnsName, location_name: 'DnsName', traits: {"smithy.api#documentation" => "<p>The DNS identifier assigned to the instance that is running the game session. Values have\n            the following format:</p>\n         <ul>\n            <li>\n               <p>TLS-enabled fleets: <code><unique identifier>.<region identifier>.amazongamelift.com</code>.</p>\n            </li>\n            <li>\n               <p>Non-TLS-enabled fleets: <code>ec2-<unique identifier>.compute.amazonaws.com</code>. (See\n            <a href=\"https://docs.aws.amazon.com/AWSEC2/latest/UserGuide/using-instance-addressing.html#concepts-public-addresses\">Amazon EC2 Instance IP Addressing</a>.)</p>\n            </li>\n         </ul>\n         <p>When connecting to a game session that is running on a TLS-enabled fleet, you must use the DNS name, not the IP address.</p>"}))
