    PutScalingPolicyInput.add_member(:name, Smithy::Schema::Shapes::ShapeRef.new(shape: NonZeroAndMaxString, location_name: 'Name', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>A descriptive label that is associated with a fleet's scaling policy. Policy names do not need to be unique. A fleet can have only one scaling policy with the same name.</p>", "smithy.api#required" => {}}))
    PutScalingPolicyInput.add_member(:fleet_id, Smithy::Schema::Shapes::ShapeRef.new(shape: FleetIdOrArn, location_name: 'FleetId', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>A unique identifier for the fleet to apply this policy to. You can use either the fleet ID or ARN value. The fleet\n            cannot be in any of the following statuses: ERROR or DELETING.</p>", "smithy.api#required" => {}}))
    PutScalingPolicyInput.add_member(:scaling_adjustment, Smithy::Schema::Shapes::ShapeRef.new(shape: Integer, location_name: 'ScalingAdjustment', traits: {"smithy.api#documentation" => "<p>Amount of adjustment to make, based on the scaling adjustment type.</p>"}))
    PutScalingPolicyInput.add_member(:scaling_adjustment_type, Smithy::Schema::Shapes::ShapeRef.new(shape: ScalingAdjustmentType, location_name: 'ScalingAdjustmentType', traits: {"smithy.api#documentation" => "<p>The type of adjustment to make to a fleet's instance count:</p>\n         <ul>\n            <li>\n               <p>\n                  <b>ChangeInCapacity</b> -- add (or subtract) the\n                    scaling adjustment value from the current instance count. Positive values scale\n                    up while negative values scale down.</p>\n            </li>\n            <li>\n               <p>\n                  <b>ExactCapacity</b> -- set the instance count to the\n                    scaling adjustment value.</p>\n            </li>\n            <li>\n               <p>\n                  <b>PercentChangeInCapacity</b> -- increase or reduce\n                    the current instance count by the scaling adjustment, read as a percentage.\n                    Positive values scale up while negative values scale down; for example, a value\n                    of \"-10\" scales the fleet down by 10%.</p>\n            </li>\n         </ul>"}))
    PutScalingPolicyInput.add_member(:threshold, Smithy::Schema::Shapes::ShapeRef.new(shape: Double, location_name: 'Threshold', traits: {"smithy.api#documentation" => "<p>Metric value used to trigger a scaling event.</p>"}))
    PutScalingPolicyInput.add_member(:comparison_operator, Smithy::Schema::Shapes::ShapeRef.new(shape: ComparisonOperatorType, location_name: 'ComparisonOperator', traits: {"smithy.api#documentation" => "<p>Comparison operator to use when measuring the metric against the threshold\n            value.</p>"}))
    PutScalingPolicyInput.add_member(:evaluation_periods, Smithy::Schema::Shapes::ShapeRef.new(shape: PositiveInteger, location_name: 'EvaluationPeriods', traits: {"smithy.api#documentation" => "<p>Length of time (in minutes) the metric must be at or beyond the threshold before a\n            scaling event is triggered.</p>"}))
    PutScalingPolicyInput.add_member(:metric_name, Smithy::Schema::Shapes::ShapeRef.new(shape: MetricName, location_name: 'MetricName', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>Name of the Amazon GameLift Servers-defined metric that is used to trigger a scaling adjustment. For\n            detailed descriptions of fleet metrics, see <a href=\"https://docs.aws.amazon.com/gamelift/latest/developerguide/monitoring-cloudwatch.html\">Monitor Amazon GameLift Servers\n                with Amazon CloudWatch</a>. </p>\n         <ul>\n            <li>\n               <p>\n                  <b>ActivatingGameSessions</b> -- Game sessions in\n                    the process of being created.</p>\n            </li>\n            <li>\n               <p>\n                  <b>ActiveGameSessions</b> -- Game sessions that\n                    are currently running.</p>\n            </li>\n            <li>\n               <p>\n                  <b>ActiveInstances</b> -- Fleet instances that\n                    are currently running at least one game session.</p>\n            </li>\n            <li>\n               <p>\n                  <b>AvailableGameSessions</b> -- Additional game\n                    sessions that fleet could host simultaneously, given current capacity.</p>\n            </li>\n            <li>\n               <p>\n                  <b>AvailablePlayerSessions</b> -- Empty player\n                    slots in currently active game sessions. This includes game sessions that are\n                    not currently accepting players. Reserved player slots are not\n                    included.</p>\n            </li>\n            <li>\n               <p>\n                  <b>CurrentPlayerSessions</b> -- Player slots in\n                    active game sessions that are being used by a player or are reserved for a\n                    player. </p>\n            </li>\n            <li>\n               <p>\n                  <b>IdleInstances</b> -- Active instances that are\n                    currently hosting zero game sessions. </p>\n            </li>\n            <li>\n               <p>\n                  <b>PercentAvailableGameSessions</b> -- Unused\n                    percentage of the total number of game sessions that a fleet could host\n                    simultaneously, given current capacity. Use this metric for a target-based\n                    scaling policy.</p>\n            </li>\n            <li>\n               <p>\n                  <b>PercentIdleInstances</b> -- Percentage of the\n                    total number of active instances that are hosting zero game sessions.</p>\n            </li>\n            <li>\n               <p>\n                  <b>QueueDepth</b> -- Pending game session\n                    placement requests, in any queue, where the current fleet is the top-priority\n                    destination.</p>\n            </li>\n            <li>\n               <p>\n                  <b>WaitTime</b> -- Current wait time for pending\n                    game session placement requests, in any queue, where the current fleet is the\n                    top-priority destination. </p>\n            </li>\n         </ul>", "smithy.api#required" => {}}))
    PutScalingPolicyInput.add_member(:policy_type, Smithy::Schema::Shapes::ShapeRef.new(shape: PolicyType, location_name: 'PolicyType', traits: {"smithy.api#documentation" => "<p>The type of scaling policy to create. For a target-based policy, set the parameter\n                <i>MetricName</i> to 'PercentAvailableGameSessions' and specify a\n                <i>TargetConfiguration</i>. For a rule-based policy set the following\n            parameters: <i>MetricName</i>, <i>ComparisonOperator</i>,\n                <i>Threshold</i>, <i>EvaluationPeriods</i>,\n                <i>ScalingAdjustmentType</i>, and\n                <i>ScalingAdjustment</i>.</p>"}))
