    RuntimeConfiguration.add_member(:max_concurrent_game_session_activations, Smithy::Schema::Shapes::ShapeRef.new(shape: MaxConcurrentGameSessionActivations, location_name: 'MaxConcurrentGameSessionActivations', traits: {"smithy.api#documentation" => "<p>The number of game sessions in status <code>ACTIVATING</code> to allow on an\n            instance or compute. This setting limits the instance resources that can be\n            used for new game activations at any one time.</p>"}))
    RuntimeConfiguration.add_member(:game_session_activation_timeout_seconds, Smithy::Schema::Shapes::ShapeRef.new(shape: GameSessionActivationTimeoutSeconds, location_name: 'GameSessionActivationTimeoutSeconds', traits: {"smithy.api#documentation" => "<p>The maximum amount of time (in seconds) allowed to launch a new game session and have\n            it report ready to host players. During this time, the game session is in status\n                <code>ACTIVATING</code>. If the game session does not become active before the\n            timeout, it is ended and the game session status is changed to\n            <code>TERMINATED</code>.</p>"}))
    RuntimeConfiguration.type = Types::RuntimeConfiguration
