    ScalingAdjustmentType.add_member(:change_in_capacity, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'ChangeInCapacity', traits: {"smithy.api#enumValue" => "ChangeInCapacity"}))
    ScalingAdjustmentType.add_member(:exact_capacity, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'ExactCapacity', traits: {"smithy.api#enumValue" => "ExactCapacity"}))
