    Script.add_member(:script_id, Smithy::Schema::Shapes::ShapeRef.new(shape: ScriptId, location_name: 'ScriptId', traits: {"smithy.api#documentation" => "<p>A unique identifier for the Realtime script</p>"}))
    Script.add_member(:script_arn, Smithy::Schema::Shapes::ShapeRef.new(shape: ScriptArn, location_name: 'ScriptArn', traits: {"smithy.api#documentation" => "<p>The Amazon Resource Name (<a href=\"https://docs.aws.amazon.com/AmazonS3/latest/dev/s3-arn-format.html\">ARN</a>) that is assigned to a Amazon GameLift Servers script resource and uniquely identifies it. ARNs are unique across all Regions. In a GameLift script ARN, the resource ID matches the\n                <i>ScriptId</i> value.</p>"}))
    Script.add_member(:name, Smithy::Schema::Shapes::ShapeRef.new(shape: NonZeroAndMaxString, location_name: 'Name', traits: {"smithy.api#documentation" => "<p>A descriptive label that is associated with a script. Script names do not need to be unique.</p>"}))
    Script.add_member(:version, Smithy::Schema::Shapes::ShapeRef.new(shape: NonZeroAndMaxString, location_name: 'Version', traits: {"smithy.api#documentation" => "<p>Version information that is associated with a build or script. Version strings do not need to be unique.</p>"}))
    Script.add_member(:size_on_disk, Smithy::Schema::Shapes::ShapeRef.new(shape: PositiveLong, location_name: 'SizeOnDisk', traits: {"smithy.api#documentation" => "<p>The file size of the uploaded Realtime script, expressed in bytes. When files are\n            uploaded from an S3 location, this value remains at \"0\".</p>"}))
    Script.add_member(:creation_time, Smithy::Schema::Shapes::ShapeRef.new(shape: Timestamp, location_name: 'CreationTime', traits: {"smithy.api#documentation" => "<p>A time stamp indicating when this data object was created. Format is a number expressed in Unix time as milliseconds (for example <code>\"1469498468.057\"</code>).</p>"}))
    Script.add_member(:storage_location, Smithy::Schema::Shapes::ShapeRef.new(shape: S3Location, location_name: 'StorageLocation', traits: {"smithy.api#documentation" => "<p>The location of the Amazon S3 bucket where a zipped file containing your Realtime scripts is\n            stored. The storage location must specify the Amazon S3 bucket name, the zip file name (the\n            \"key\"), and a role ARN that allows Amazon GameLift Servers to access the Amazon S3 storage location. The S3\n            bucket must be in the same Region where you want to create a new script. By default,\n            Amazon GameLift Servers uploads the latest version of the zip file; if you have S3 object versioning\n            turned on, you can use the <code>ObjectVersion</code> parameter to specify an earlier\n            version. </p>"}))
