    SearchGameSessionsInput.add_member(:fleet_id, Smithy::Schema::Shapes::ShapeRef.new(shape: FleetIdOrArn, location_name: 'FleetId', traits: {"smithy.api#documentation" => "<p>A unique identifier for the fleet to search for active game sessions. You can use either the fleet ID or ARN\n            value. Each request must reference either a fleet ID or alias ID, but not both.</p>"}))
    SearchGameSessionsInput.add_member(:alias_id, Smithy::Schema::Shapes::ShapeRef.new(shape: AliasIdOrArn, location_name: 'AliasId', traits: {"smithy.api#documentation" => "<p>A unique identifier for the alias associated with the fleet to search for active game sessions. You can use either\n            the alias ID or ARN value. Each request must reference either a fleet ID or alias ID,\n            but not both.</p>"}))
    SearchGameSessionsInput.add_member(:location, Smithy::Schema::Shapes::ShapeRef.new(shape: LocationStringModel, location_name: 'Location', traits: {"smithy.api#documentation" => "<p>A fleet location to search for game sessions. You can specify a fleet's home Region or\n            a remote location. Use the Amazon Web Services Region code format, such as <code>us-west-2</code>.\n        </p>"}))
    SearchGameSessionsInput.add_member(:filter_expression, Smithy::Schema::Shapes::ShapeRef.new(shape: NonZeroAndMaxString, location_name: 'FilterExpression', traits: {"smithy.api#documentation" => "<p>String containing the search criteria for the session search. If no filter expression\n            is included, the request returns results for all game sessions in the fleet that are in\n                <code>ACTIVE</code> status.</p>\n         <p>A filter expression can contain one or multiple conditions. Each condition consists of\n            the following:</p>\n         <ul>\n            <li>\n               <p>\n                  <b>Operand</b> -- Name of a game session attribute.\n                    Valid values are <code>gameSessionName</code>, <code>gameSessionId</code>,\n                        <code>gameSessionProperties</code>, <code>maximumSessions</code>,\n                        <code>creationTimeMillis</code>, <code>playerSessionCount</code>,\n                        <code>hasAvailablePlayerSessions</code>.</p>\n            </li>\n            <li>\n               <p>\n                  <b>Comparator</b> -- Valid comparators are:\n                        <code>=</code>, <code><></code>, <code><</code>, <code>></code>,\n                        <code><=</code>, <code>>=</code>. </p>\n            </li>\n            <li>\n               <p>\n                  <b>Value</b> -- Value to be searched for. Values may\n                    be numbers, boolean values (true/false) or strings depending on the operand.\n                    String values are case sensitive and must be enclosed in single quotes. Special\n                    characters must be escaped. Boolean and string values can only be used with the\n                    comparators <code>=</code> and <code><></code>. For example, the following\n                    filter expression searches on <code>gameSessionName</code>:\n                        \"<code>FilterExpression\": \"gameSessionName = 'Matt\\\\'s Awesome Game\n                        1'\"</code>. </p>\n            </li>\n         </ul>\n         <p>To chain multiple conditions in a single expression, use the logical keywords\n                <code>AND</code>, <code>OR</code>, and <code>NOT</code> and parentheses as needed.\n            For example: <code>x AND y AND NOT z</code>, <code>NOT (x OR y)</code>.</p>\n         <p>Session search evaluates conditions from left to right using the following precedence\n            rules:</p>\n         <ol>\n            <li>\n               <p>\n                  <code>=</code>, <code><></code>, <code><</code>, <code>></code>,\n                        <code><=</code>, <code>>=</code>\n               </p>\n            </li>\n            <li>\n               <p>Parentheses</p>\n            </li>\n            <li>\n               <p>NOT</p>\n            </li>\n            <li>\n               <p>AND</p>\n            </li>\n            <li>\n               <p>OR</p>\n            </li>\n         </ol>\n         <p>For example, this filter expression retrieves game sessions hosting at least ten\n            players that have an open player slot: <code>\"maximumSessions>=10 AND\n                hasAvailablePlayerSessions=true\"</code>. </p>"}))
    SearchGameSessionsInput.add_member(:sort_expression, Smithy::Schema::Shapes::ShapeRef.new(shape: NonZeroAndMaxString, location_name: 'SortExpression', traits: {"smithy.api#documentation" => "<p>Instructions on how to sort the search results. If no sort expression is included, the\n            request returns results in random order. A sort expression consists of the following\n            elements:</p>\n         <ul>\n            <li>\n               <p>\n                  <b>Operand</b> -- Name of a game session attribute.\n                    Valid values are <code>gameSessionName</code>, <code>gameSessionId</code>,\n                        <code>gameSessionProperties</code>, <code>maximumSessions</code>,\n                        <code>creationTimeMillis</code>, <code>playerSessionCount</code>,\n                        <code>hasAvailablePlayerSessions</code>.</p>\n            </li>\n            <li>\n               <p>\n                  <b>Order</b> -- Valid sort orders are <code>ASC</code>\n                    (ascending) and <code>DESC</code> (descending).</p>\n            </li>\n         </ul>\n         <p>For example, this sort expression returns the oldest active sessions first:\n                <code>\"SortExpression\": \"creationTimeMillis ASC\"</code>. Results with a null value\n            for the sort operand are returned at the end of the list.</p>"}))
    SearchGameSessionsInput.add_member(:limit, Smithy::Schema::Shapes::ShapeRef.new(shape: PositiveInteger, location_name: 'Limit', traits: {"smithy.api#documentation" => "<p>The maximum number of results to return. Use this parameter with <code>NextToken</code> to get results as a set of sequential pages. The maximum number of results returned is 20, even if this value is not set or\n            is set higher than 20. </p>"}))
    SearchGameSessionsInput.add_member(:next_token, Smithy::Schema::Shapes::ShapeRef.new(shape: NonZeroAndMaxString, location_name: 'NextToken', traits: {"smithy.api#documentation" => "<p>A token that indicates the start of the next sequential page of results. Use the token that is returned with a previous call to this operation. To start at the beginning of the result set, do not specify a value.</p>"}))
    SearchGameSessionsInput.type = Types::SearchGameSessionsInput
    SearchGameSessionsOutput.add_member(:game_sessions, Smithy::Schema::Shapes::ShapeRef.new(shape: GameSessionList, location_name: 'GameSessions', traits: {"smithy.api#documentation" => "<p>A collection of objects containing game session properties for each session that\n            matches the request.</p>"}))
    SearchGameSessionsOutput.add_member(:next_token, Smithy::Schema::Shapes::ShapeRef.new(shape: NonZeroAndMaxString, location_name: 'NextToken', traits: {"smithy.api#documentation" => "<p>A token that indicates where to resume retrieving results on the next call to this operation. If no token is returned, these results represent the end of the list.</p>"}))
