    StartMatchmakingInput.add_member(:configuration_name, Smithy::Schema::Shapes::ShapeRef.new(shape: MatchmakingConfigurationName, location_name: 'ConfigurationName', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>Name of the matchmaking configuration to use for this request. Matchmaking\n            configurations must exist in the same Region as this request. You can use either the\n            configuration name or ARN value.</p>", "smithy.api#required" => {}}))
    StartMatchmakingInput.add_member(:players, Smithy::Schema::Shapes::ShapeRef.new(shape: PlayerList, location_name: 'Players', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>Information on each player to be matched. This information must include a player ID,\n            and may contain player attributes and latency data to be used in the matchmaking\n            process. After a successful match, <code>Player</code> objects contain the name of the\n            team the player is assigned to.</p>\n         <p>You can include up to 10 <code>Players</code> in a <code>StartMatchmaking</code>\n            request.</p>", "smithy.api#required" => {}}))
