    SupportContainerDefinition.add_member(:depends_on, Smithy::Schema::Shapes::ShapeRef.new(shape: ContainerDependencyList, location_name: 'DependsOn', traits: {"smithy.api#documentation" => "<p>Indicates that the container relies on the status of other containers in the same\n      container group during its startup and shutdown sequences. A container might have dependencies\n      on multiple containers.</p>"}))
