    SupportContainerDefinition.add_member(:health_check, Smithy::Schema::Shapes::ShapeRef.new(shape: ContainerHealthCheck, location_name: 'HealthCheck', traits: {"smithy.api#documentation" => "<p>A configuration for a non-terminal health check. A support container automatically\n      restarts if it stops functioning or if it fails this health check. </p>"}))
    SupportContainerDefinition.add_member(:image_uri, Smithy::Schema::Shapes::ShapeRef.new(shape: ImageUriString, location_name: 'ImageUri', traits: {"smithy.api#documentation" => "<p>The URI to the image that Amazon GameLift Servers deploys to a container fleet. For a more specific\n      identifier, see <code>ResolvedImageDigest</code>. </p>"}))
    SupportContainerDefinition.add_member(:memory_hard_limit_mebibytes, Smithy::Schema::Shapes::ShapeRef.new(shape: ContainerMemoryLimit, location_name: 'MemoryHardLimitMebibytes', traits: {"smithy.api#documentation" => "<p>The amount of memory that Amazon GameLift Servers makes available to the container. If memory limits\n      aren't set for an individual container, the container shares the container group's total\n      memory allocation.</p>\n         <p>\n            <b>Related data type: </b>\n            <a href=\"https://docs.aws.amazon.com/gamelift/latest/apireference/API_ContainerGroupDefinition.html\">ContainerGroupDefinition TotalMemoryLimitMebibytes</a>\n         </p>"}))
    SupportContainerDefinition.add_member(:port_configuration, Smithy::Schema::Shapes::ShapeRef.new(shape: ContainerPortConfiguration, location_name: 'PortConfiguration', traits: {"smithy.api#documentation" => "<p>A set of ports that allow access to the container from external users. Processes running\n      in the container can bind to a one of these ports. Container ports aren't directly accessed by\n      inbound traffic. Amazon GameLift Servers maps these container ports to externally accessible connection ports,\n      which are assigned as needed from the container fleet's\n      <code>ConnectionPortRange</code>.</p>"}))
    SupportContainerDefinition.add_member(:resolved_image_digest, Smithy::Schema::Shapes::ShapeRef.new(shape: Sha256, location_name: 'ResolvedImageDigest', traits: {"smithy.api#documentation" => "<p>A unique and immutable identifier for the container image. The digest is a SHA 256 hash of\n      the container image manifest. </p>"}))
    SupportContainerDefinition.add_member(:vcpu, Smithy::Schema::Shapes::ShapeRef.new(shape: ContainerVcpu, location_name: 'Vcpu', traits: {"smithy.api#documentation" => "<p>The number of vCPU units that are reserved for the container. If no resources are\n      reserved, the container shares the total vCPU limit for the container group.</p>\n         <p>\n            <b>Related data type: </b>\n            <a href=\"https://docs.aws.amazon.com/gamelift/latest/apireference/API_ContainerGroupDefinition.html\">ContainerGroupDefinition TotalVcpuLimit</a>\n         </p>"}))
    SupportContainerDefinition.type = Types::SupportContainerDefinition
    SupportContainerDefinitionInput.add_member(:container_name, Smithy::Schema::Shapes::ShapeRef.new(shape: NonZeroAnd128MaxAsciiString, location_name: 'ContainerName', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>A string that uniquely identifies the container definition within a container\n      group.</p>", "smithy.api#required" => {}}))
    SupportContainerDefinitionInput.add_member(:depends_on, Smithy::Schema::Shapes::ShapeRef.new(shape: ContainerDependencyList, location_name: 'DependsOn', traits: {"smithy.api#documentation" => "<p>Establishes dependencies between this container and the status of other containers in the\n      same container group. A container can have dependencies on multiple different containers. </p>\n         <p>.</p>\n         <p>You can use dependencies to establish a startup/shutdown sequence across the container\n      group. For example, you might specify that <i>ContainerB</i> has a\n        <code>START</code> dependency on <i>ContainerA</i>. This dependency means that\n        <i>ContainerB</i> can't start until after <i>ContainerA</i> has\n      started. This dependency is reversed on shutdown, which means that\n        <i>ContainerB</i> must shut down before <i>ContainerA</i> can\n      shut down. </p>"}))
    SupportContainerDefinitionInput.add_member(:mount_points, Smithy::Schema::Shapes::ShapeRef.new(shape: ContainerMountPointList, location_name: 'MountPoints', traits: {"smithy.api#documentation" => "<p>A mount point that binds a path inside the container to a file or directory on the host\n      system and lets it access the file or directory.</p>"}))
    SupportContainerDefinitionInput.add_member(:environment_override, Smithy::Schema::Shapes::ShapeRef.new(shape: ContainerEnvironmentList, location_name: 'EnvironmentOverride', traits: {"smithy.api#documentation" => "<p>A set of environment variables to pass to the container on startup. See the <a href=\"https://docs.aws.amazon.com/AmazonECS/latest/APIReference/API_ContainerDefinition.html#ECS-Type-ContainerDefinition-environment\">ContainerDefinition::environment</a> parameter in the <i>Amazon Elastic Container Service API\n        Reference</i>. </p>"}))
    SupportContainerDefinitionInput.add_member(:essential, Smithy::Schema::Shapes::ShapeRef.new(shape: BooleanModel, location_name: 'Essential', traits: {"smithy.api#documentation" => "<p>Flags the container as vital for the container group to function properly. If an essential\n      container fails, the entire container group restarts. At least one support container in a\n      per-instance container group must be essential. When flagging a container as essential, also\n      configure a health check so that the container can signal that it's healthy. </p>"}))
    SupportContainerDefinitionInput.add_member(:health_check, Smithy::Schema::Shapes::ShapeRef.new(shape: ContainerHealthCheck, location_name: 'HealthCheck', traits: {"smithy.api#documentation" => "<p>Configuration for a non-terminal health check. A container automatically restarts if it\n      stops functioning. With a health check, you can define additional reasons to flag a container\n      as unhealthy and restart it. If an essential container fails a health check, the entire\n      container group restarts. </p>"}))
    SupportContainerDefinitionInput.add_member(:image_uri, Smithy::Schema::Shapes::ShapeRef.new(shape: ImageUriString, location_name: 'ImageUri', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>The location of the container image to deploy to a container fleet. Provide an image in an\n      Amazon Elastic Container Registry public or private repository. The repository must be in the same Amazon Web Services account and\n      Amazon Web Services Region where you're creating the container group definition. For limits on image size,\n      see <a href=\"https://docs.aws.amazon.com/general/latest/gr/gamelift.html\">Amazon GameLift Servers endpoints and\n        quotas</a>. You can use any of the following image URI formats: </p>\n         <ul>\n            <li>\n               <p>Image ID only: <code>[AWS account].dkr.ecr.[AWS region].amazonaws.com/[repository\n          ID]</code>\n               </p>\n            </li>\n            <li>\n               <p>Image ID and digest: <code>[AWS account].dkr.ecr.[AWS\n          region].amazonaws.com/[repository ID]@[digest]</code>\n               </p>\n            </li>\n            <li>\n               <p>Image ID and tag: <code>[AWS account].dkr.ecr.[AWS region].amazonaws.com/[repository\n          ID]:[tag]</code>\n               </p>\n            </li>\n         </ul>", "smithy.api#required" => {}}))
    SupportContainerDefinitionInput.add_member(:memory_hard_limit_mebibytes, Smithy::Schema::Shapes::ShapeRef.new(shape: ContainerMemoryLimit, location_name: 'MemoryHardLimitMebibytes', traits: {"smithy.api#documentation" => "<p>A specified amount of memory (in MiB) to reserve for this container. If you don't specify\n      a container-specific memory limit, the container shares the container group's total memory\n      allocation. </p>\n         <p>\n            <b>Related data type: </b>\n            <a href=\"https://docs.aws.amazon.com/gamelift/latest/apireference/API_ContainerGroupDefinition.html\">ContainerGroupDefinition</a>TotalMemoryLimitMebibytes<code></code>\n         </p>"}))
    SupportContainerDefinitionInput.add_member(:port_configuration, Smithy::Schema::Shapes::ShapeRef.new(shape: ContainerPortConfiguration, location_name: 'PortConfiguration', traits: {"smithy.api#documentation" => "<p>A set of ports that Amazon GameLift Servers can assign to processes in a container. The container port\n      configuration must have enough ports for each container process that accepts inbound traffic\n      connections. A container port configuration can have can have one or more container port\n      ranges. Each range specifies starting and ending values as well as the supported network\n      protocol.</p>\n         <p>Container ports aren't directly accessed by inbound traffic. Amazon GameLift Servers maps each container\n      port to an externally accessible connection port (see the container fleet property\n        <code>ConnectionPortRange</code>). </p>"}))
