    UpdateContainerGroupDefinitionInput.add_member(:total_memory_limit_mebibytes, Smithy::Schema::Shapes::ShapeRef.new(shape: ContainerTotalMemoryLimit, location_name: 'TotalMemoryLimitMebibytes', traits: {"smithy.api#documentation" => "<p>The maximum amount of memory (in MiB) to allocate to the container group. All containers in\n      the group share this memory. If you specify memory limits for an individual container, the\n      total value must be greater than any individual container's memory limit.</p>"}))
