    UpdateFleetAttributesInput.add_member(:new_game_session_protection_policy, Smithy::Schema::Shapes::ShapeRef.new(shape: ProtectionPolicy, location_name: 'NewGameSessionProtectionPolicy', traits: {"smithy.api#documentation" => "<p>The game session protection policy to apply to all new game sessions created in this\n            fleet. Game sessions that already exist are not affected. You can set protection for\n            individual game sessions using <a href=\"https://docs.aws.amazon.com/gamelift/latest/apireference/API_UpdateGameSession.html\">UpdateGameSession</a> .</p>\n         <ul>\n            <li>\n               <p>\n                  <b>NoProtection</b> -- The game session can be\n                    terminated during a scale-down event.</p>\n            </li>\n            <li>\n               <p>\n                  <b>FullProtection</b> -- If the game session is in an\n                        <code>ACTIVE</code> status, it cannot be terminated during a scale-down\n                    event.</p>\n            </li>\n         </ul>"}))
