    UpdateFleetAttributesInput.add_member(:metric_groups, Smithy::Schema::Shapes::ShapeRef.new(shape: MetricGroupList, location_name: 'MetricGroups', traits: {"smithy.api#documentation" => "<p>The name of a metric group to add this fleet to. Use a metric group in Amazon\n            CloudWatch to aggregate the metrics from multiple fleets. Provide an existing metric\n            group name, or create a new metric group by providing a new name. A fleet can only be in\n            one metric group at a time.</p>"}))
    UpdateFleetAttributesInput.add_member(:anywhere_configuration, Smithy::Schema::Shapes::ShapeRef.new(shape: AnywhereConfiguration, location_name: 'AnywhereConfiguration', traits: {"smithy.api#documentation" => "<p>Amazon GameLift Servers Anywhere configuration options.</p>"}))
    UpdateFleetAttributesInput.type = Types::UpdateFleetAttributesInput
    UpdateFleetAttributesOutput.add_member(:fleet_id, Smithy::Schema::Shapes::ShapeRef.new(shape: FleetId, location_name: 'FleetId', traits: {"smithy.api#documentation" => "<p>A unique identifier for the fleet that was updated.</p>"}))
    UpdateFleetAttributesOutput.add_member(:fleet_arn, Smithy::Schema::Shapes::ShapeRef.new(shape: FleetArn, location_name: 'FleetArn', traits: {"smithy.api#documentation" => "<p>The Amazon Resource Name (<a href=\"https://docs.aws.amazon.com/AmazonS3/latest/dev/s3-arn-format.html\">ARN</a>) that is assigned to a Amazon GameLift Servers fleet resource and uniquely identifies it. ARNs are unique across all Regions. Format is <code>arn:aws:gamelift:<region>::fleet/fleet-a1234567-b8c9-0d1e-2fa3-b45c6d7e8912</code>.</p>"}))
    UpdateFleetAttributesOutput.type = Types::UpdateFleetAttributesOutput
    UpdateFleetCapacityInput.add_member(:fleet_id, Smithy::Schema::Shapes::ShapeRef.new(shape: FleetIdOrArn, location_name: 'FleetId', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>A unique identifier for the fleet to update capacity settings for. You can use either the fleet ID or ARN\n            value.</p>", "smithy.api#required" => {}}))
    UpdateFleetCapacityInput.add_member(:desired_instances, Smithy::Schema::Shapes::ShapeRef.new(shape: WholeNumber, location_name: 'DesiredInstances', traits: {"smithy.api#documentation" => "<p>The number of Amazon EC2 instances you want to maintain in the specified fleet location.\n            This value must fall between the minimum and maximum size limits. Changes in desired\n            instance value can take up to 1 minute to be reflected when viewing the fleet's capacity\n            settings.</p>"}))
    UpdateFleetCapacityInput.add_member(:min_size, Smithy::Schema::Shapes::ShapeRef.new(shape: WholeNumber, location_name: 'MinSize', traits: {"smithy.api#documentation" => "<p>The minimum number of instances that are allowed in the specified fleet location. If\n            this parameter is not set, the default is 0.</p>"}))
    UpdateFleetCapacityInput.add_member(:max_size, Smithy::Schema::Shapes::ShapeRef.new(shape: WholeNumber, location_name: 'MaxSize', traits: {"smithy.api#documentation" => "<p>The maximum number of instances that are allowed in the specified fleet location. If\n            this parameter is not set, the default is 1.</p>"}))
    UpdateFleetCapacityInput.add_member(:location, Smithy::Schema::Shapes::ShapeRef.new(shape: LocationStringModel, location_name: 'Location', traits: {"smithy.api#documentation" => "<p>The name of a remote location to update fleet capacity settings for, in the form of an\n            Amazon Web Services Region code such as <code>us-west-2</code>.</p>"}))
