    UpdateFleetPortSettingsOutput.type = Types::UpdateFleetPortSettingsOutput
    UpdateGameServerGroupInput.add_member(:game_server_group_name, Smithy::Schema::Shapes::ShapeRef.new(shape: GameServerGroupNameOrArn, location_name: 'GameServerGroupName', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>A unique identifier for the game server group. Use either the name or ARN value.</p>", "smithy.api#required" => {}}))
    UpdateGameServerGroupInput.add_member(:role_arn, Smithy::Schema::Shapes::ShapeRef.new(shape: IamRoleArn, location_name: 'RoleArn', traits: {"smithy.api#documentation" => "<p>The Amazon Resource Name (<a href=\"https://docs.aws.amazon.com/AmazonS3/latest/dev/s3-arn-format.html\">ARN</a>) for an IAM role that\n            allows Amazon GameLift Servers to access your Amazon EC2 Auto Scaling groups.</p>"}))
    UpdateGameServerGroupInput.add_member(:instance_definitions, Smithy::Schema::Shapes::ShapeRef.new(shape: InstanceDefinitions, location_name: 'InstanceDefinitions', traits: {"smithy.api#documentation" => "<p>An updated list of Amazon EC2 instance types to use in the Auto Scaling group. The instance\n            definitions must specify at least two different instance types that are supported by\n            Amazon GameLift Servers FleetIQ. This updated list replaces the entire current list of instance definitions for\n            the game server group. For more information on instance types, see <a href=\"https://docs.aws.amazon.com/AWSEC2/latest/UserGuide/instance-types.html\">EC2 Instance\n                Types</a> in the <i>Amazon EC2 User Guide</i>. You can optionally\n            specify capacity weighting for each instance type. If no weight value is specified for\n            an instance type, it is set to the default value \"1\". For more information about\n            capacity weighting, see <a href=\"https://docs.aws.amazon.com/autoscaling/ec2/userguide/asg-instance-weighting.html\"> Instance Weighting for\n                Amazon EC2 Auto Scaling</a> in the Amazon EC2 Auto Scaling User Guide.</p>"}))
    UpdateGameServerGroupInput.add_member(:game_server_protection_policy, Smithy::Schema::Shapes::ShapeRef.new(shape: GameServerProtectionPolicy, location_name: 'GameServerProtectionPolicy', traits: {"smithy.api#documentation" => "<p>A flag that indicates whether instances in the game server group are protected \n            from early termination. Unprotected instances that have active game servers running might \n            be terminated during a scale-down event, causing players to be dropped from the game. \n            Protected instances cannot be terminated while there are active game servers running except \n            in the event of a forced game server group deletion (see ). An exception to this is with Spot \n            Instances, which can be terminated by Amazon Web Services regardless of protection status. This property is set to <code>NO_PROTECTION</code> by default.</p>"}))
    UpdateGameServerGroupInput.add_member(:balancing_strategy, Smithy::Schema::Shapes::ShapeRef.new(shape: BalancingStrategy, location_name: 'BalancingStrategy', traits: {"smithy.api#documentation" => "<p>Indicates how Amazon GameLift Servers FleetIQ balances the use of Spot Instances and On-Demand Instances in the\n            game server group. Method options include the following:</p>\n         <ul>\n            <li>\n               <p>\n                  <code>SPOT_ONLY</code> - Only Spot Instances are used in the game server group. If Spot\n                    Instances are unavailable or not viable for game hosting, the game server group\n                    provides no hosting capacity until Spot Instances can again be used. Until then,\n                    no new instances are started, and the existing nonviable Spot Instances are\n                    terminated (after current gameplay ends) and are not replaced.</p>\n            </li>\n            <li>\n               <p>\n                  <code>SPOT_PREFERRED</code> - (default value) Spot Instances are used whenever available in\n                    the game server group. If Spot Instances are unavailable, the game server group\n                    continues to provide hosting capacity by falling back to On-Demand Instances.\n                    Existing nonviable Spot Instances are terminated (after current gameplay ends)\n                    and are replaced with new On-Demand Instances.</p>\n            </li>\n            <li>\n               <p>\n                  <code>ON_DEMAND_ONLY</code> - Only On-Demand Instances are used in the game\n                    server group. No Spot Instances are used, even when available, while this\n                    balancing strategy is in force.</p>\n            </li>\n         </ul>"}))
    UpdateGameServerGroupInput.type = Types::UpdateGameServerGroupInput
    UpdateGameServerGroupOutput.add_member(:game_server_group, Smithy::Schema::Shapes::ShapeRef.new(shape: GameServerGroup, location_name: 'GameServerGroup', traits: {"smithy.api#documentation" => "<p>An object that describes the game server group resource with updated properties.\n        </p>"}))
