    UpdateGameServerInput.add_member(:game_server_id, Smithy::Schema::Shapes::ShapeRef.new(shape: GameServerId, location_name: 'GameServerId', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>A custom string that uniquely identifies the game server to update.</p>", "smithy.api#required" => {}}))
    UpdateGameServerInput.add_member(:game_server_data, Smithy::Schema::Shapes::ShapeRef.new(shape: GameServerData, location_name: 'GameServerData', traits: {"smithy.api#documentation" => "<p>A set of custom game server properties, formatted as a single string value. This data \n            is passed to a game client or service when it requests information on game servers. </p>"}))
    UpdateGameServerInput.add_member(:utilization_status, Smithy::Schema::Shapes::ShapeRef.new(shape: GameServerUtilizationStatus, location_name: 'UtilizationStatus', traits: {"smithy.api#documentation" => "<p>Indicates if the game server is available or is currently hosting gameplay. You can\n            update a game server status from <code>AVAILABLE</code> to <code>UTILIZED</code>, but\n            you can't change a the status from <code>UTILIZED</code> to\n            <code>AVAILABLE</code>.</p>"}))
    UpdateGameServerInput.add_member(:health_check, Smithy::Schema::Shapes::ShapeRef.new(shape: GameServerHealthCheck, location_name: 'HealthCheck', traits: {"smithy.api#documentation" => "<p>Indicates health status of the game server. A request that includes this parameter\n            updates the game server's <i>LastHealthCheckTime</i> timestamp. </p>"}))
    UpdateGameServerInput.type = Types::UpdateGameServerInput
