    UpdateGameServerOutput.type = Types::UpdateGameServerOutput
    UpdateGameSessionInput.add_member(:game_session_id, Smithy::Schema::Shapes::ShapeRef.new(shape: ArnStringModel, location_name: 'GameSessionId', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>A unique identifier for the game session to update. </p>", "smithy.api#required" => {}}))
    UpdateGameSessionInput.add_member(:maximum_player_session_count, Smithy::Schema::Shapes::ShapeRef.new(shape: WholeNumber, location_name: 'MaximumPlayerSessionCount', traits: {"smithy.api#documentation" => "<p>The maximum number of players that can be connected simultaneously to the game session.</p>"}))
    UpdateGameSessionInput.add_member(:name, Smithy::Schema::Shapes::ShapeRef.new(shape: NonZeroAndMaxString, location_name: 'Name', traits: {"smithy.api#documentation" => "<p>A descriptive label that is associated with a game session. Session names do not need to be unique.</p>"}))
    UpdateGameSessionInput.add_member(:player_session_creation_policy, Smithy::Schema::Shapes::ShapeRef.new(shape: PlayerSessionCreationPolicy, location_name: 'PlayerSessionCreationPolicy', traits: {"smithy.api#documentation" => "<p>A policy that determines whether the game session is accepting new players.</p>"}))
    UpdateGameSessionInput.add_member(:protection_policy, Smithy::Schema::Shapes::ShapeRef.new(shape: ProtectionPolicy, location_name: 'ProtectionPolicy', traits: {"smithy.api#documentation" => "<p>Game session protection policy to apply to this game session only.</p>\n         <ul>\n            <li>\n               <p>\n                  <code>NoProtection</code> -- The game session can be terminated during a\n                    scale-down event.</p>\n            </li>\n            <li>\n               <p>\n                  <code>FullProtection</code> -- If the game session is in an\n                        <code>ACTIVE</code> status, it cannot be terminated during a scale-down\n                    event.</p>\n            </li>\n         </ul>"}))
    UpdateGameSessionInput.add_member(:game_properties, Smithy::Schema::Shapes::ShapeRef.new(shape: GamePropertyList, location_name: 'GameProperties', traits: {"smithy.api#documentation" => "<p>A set of key-value pairs that can store custom data in a game session.\n  For example: <code>{\"Key\": \"difficulty\", \"Value\": \"novice\"}</code>.\n        You can use this parameter to modify game properties in an active game session.\n        This action adds new properties and modifies existing properties.\n        There is no way to delete properties.\n        For an example, see <a href=\"https://docs.aws.amazon.com/gamelift/latest/developerguide/gamelift-sdk-client-api.html#game-properties-update\">Update the value of a game property</a>.\n      </p>"}))
    UpdateGameSessionInput.type = Types::UpdateGameSessionInput
    UpdateGameSessionOutput.add_member(:game_session, Smithy::Schema::Shapes::ShapeRef.new(shape: GameSession, location_name: 'GameSession', traits: {"smithy.api#documentation" => "<p>The updated game session properties.</p>"}))
    UpdateGameSessionOutput.type = Types::UpdateGameSessionOutput
    UpdateGameSessionQueueInput.add_member(:name, Smithy::Schema::Shapes::ShapeRef.new(shape: GameSessionQueueNameOrArn, location_name: 'Name', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>A descriptive label that is associated with game session queue. Queue names must be unique within each Region. You can use either the queue ID or ARN value. </p>", "smithy.api#required" => {}}))
    UpdateGameSessionQueueInput.add_member(:timeout_in_seconds, Smithy::Schema::Shapes::ShapeRef.new(shape: WholeNumber, location_name: 'TimeoutInSeconds', traits: {"smithy.api#documentation" => "<p>The maximum time, in seconds, that a new game session placement request remains in the queue. When a request exceeds this time, the game session placement changes to a <code>TIMED_OUT</code> status.</p>"}))
    UpdateGameSessionQueueInput.add_member(:player_latency_policies, Smithy::Schema::Shapes::ShapeRef.new(shape: PlayerLatencyPolicyList, location_name: 'PlayerLatencyPolicies', traits: {"smithy.api#documentation" => "<p>A set of policies that enforce a sliding cap on player latency when processing game sessions placement requests. \n\tUse multiple policies to gradually relax the cap over time if Amazon GameLift Servers can't make a placement.\n\t    Policies are evaluated in order starting with the lowest maximum latency value. When updating policies, provide a complete collection of policies.</p>"}))
    UpdateGameSessionQueueInput.add_member(:destinations, Smithy::Schema::Shapes::ShapeRef.new(shape: GameSessionQueueDestinationList, location_name: 'Destinations', traits: {"smithy.api#documentation" => "<p>A list of fleets and/or fleet aliases that can be used to fulfill game session placement requests in the queue. \n    Destinations are identified by either a fleet ARN or a fleet alias ARN, and are listed in order of placement preference. When updating this list, provide a complete list of destinations.</p>"}))
    UpdateGameSessionQueueInput.add_member(:filter_configuration, Smithy::Schema::Shapes::ShapeRef.new(shape: FilterConfiguration, location_name: 'FilterConfiguration', traits: {"smithy.api#documentation" => "<p>A list of locations where a queue is allowed to place new game sessions. Locations \n            are specified in the form of Amazon Web Services Region codes, such as <code>us-west-2</code>. If this parameter is \n            not set, game sessions can be placed in any queue location. To remove an existing filter configuration, pass in an empty set.</p>"}))
    UpdateGameSessionQueueInput.add_member(:priority_configuration, Smithy::Schema::Shapes::ShapeRef.new(shape: PriorityConfiguration, location_name: 'PriorityConfiguration', traits: {"smithy.api#documentation" => "<p>Custom settings to use when prioritizing destinations and locations for game session placements. This \n            configuration replaces the FleetIQ default prioritization process. Priority types that are not explicitly \n            named will be automatically applied at the end of the prioritization process. To remove an existing priority configuration, pass in an empty set.</p>"}))
    UpdateGameSessionQueueInput.add_member(:custom_event_data, Smithy::Schema::Shapes::ShapeRef.new(shape: QueueCustomEventData, location_name: 'CustomEventData', traits: {"smithy.api#documentation" => "<p>Information to be added to all events that are related to this game session\n            queue.</p>"}))
    UpdateGameSessionQueueInput.add_member(:notification_target, Smithy::Schema::Shapes::ShapeRef.new(shape: QueueSnsArnStringModel, location_name: 'NotificationTarget', traits: {"smithy.api#documentation" => "<p>An SNS topic ARN that is set up to receive game session placement notifications. See\n                <a href=\"https://docs.aws.amazon.com/gamelift/latest/developerguide/queue-notification.html\"> Setting up\n                notifications for game session placement</a>.</p>"}))
    UpdateGameSessionQueueInput.type = Types::UpdateGameSessionQueueInput
