    UpdateGameSessionQueueOutput.type = Types::UpdateGameSessionQueueOutput
    UpdateMatchmakingConfigurationInput.add_member(:name, Smithy::Schema::Shapes::ShapeRef.new(shape: MatchmakingConfigurationName, location_name: 'Name', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>A unique identifier for the matchmaking configuration to update. You can use either the configuration name or ARN value. </p>", "smithy.api#required" => {}}))
    UpdateMatchmakingConfigurationInput.add_member(:description, Smithy::Schema::Shapes::ShapeRef.new(shape: NonZeroAndMaxString, location_name: 'Description', traits: {"smithy.api#documentation" => "<p>A description for the matchmaking configuration.</p>"}))
    UpdateMatchmakingConfigurationInput.add_member(:game_session_queue_arns, Smithy::Schema::Shapes::ShapeRef.new(shape: QueueArnsList, location_name: 'GameSessionQueueArns', traits: {"smithy.api#documentation" => "<p>The Amazon Resource Name (<a href=\"https://docs.aws.amazon.com/AmazonS3/latest/dev/s3-arn-format.html\">ARN</a>) that is assigned to a Amazon GameLift Servers game session queue resource and uniquely identifies it. ARNs are unique across all Regions. Format is <code>arn:aws:gamelift:<region>::gamesessionqueue/<queue name></code>. Queues can be located in any Region. Queues are used to start new\n            Amazon GameLift Servers-hosted game sessions for matches that are created with this matchmaking\n            configuration. If <code>FlexMatchMode</code> is set to <code>STANDALONE</code>, do not\n            set this parameter.</p>"}))
    UpdateMatchmakingConfigurationInput.add_member(:request_timeout_seconds, Smithy::Schema::Shapes::ShapeRef.new(shape: MatchmakingRequestTimeoutInteger, location_name: 'RequestTimeoutSeconds', traits: {"smithy.api#documentation" => "<p>The maximum duration, in seconds, that a matchmaking ticket can remain in process\n            before timing out. Requests that fail due to timing out can be resubmitted as\n            needed.</p>"}))
    UpdateMatchmakingConfigurationInput.add_member(:acceptance_timeout_seconds, Smithy::Schema::Shapes::ShapeRef.new(shape: MatchmakingAcceptanceTimeoutInteger, location_name: 'AcceptanceTimeoutSeconds', traits: {"smithy.api#documentation" => "<p>The length of time (in seconds) to wait for players to accept a proposed match, if\n            acceptance is required.</p>"}))
    UpdateMatchmakingConfigurationInput.add_member(:acceptance_required, Smithy::Schema::Shapes::ShapeRef.new(shape: BooleanModel, location_name: 'AcceptanceRequired', traits: {"smithy.api#documentation" => "<p>A flag that indicates whether a match that was created with this configuration must be\n            accepted by the matched players. To require acceptance, set to TRUE. With this option\n            enabled, matchmaking tickets use the status <code>REQUIRES_ACCEPTANCE</code> to indicate\n            when a completed potential match is waiting for player acceptance. </p>"}))
    UpdateMatchmakingConfigurationInput.add_member(:rule_set_name, Smithy::Schema::Shapes::ShapeRef.new(shape: MatchmakingRuleSetName, location_name: 'RuleSetName', traits: {"smithy.api#documentation" => "<p>A unique identifier for the matchmaking rule set to use with this configuration. You can use either the rule set name or ARN\n            value. A matchmaking configuration can only use rule sets that are defined in the same\n            Region.</p>"}))
    UpdateMatchmakingConfigurationInput.add_member(:notification_target, Smithy::Schema::Shapes::ShapeRef.new(shape: SnsArnStringModel, location_name: 'NotificationTarget', traits: {"smithy.api#documentation" => "<p>An SNS topic ARN that is set up to receive matchmaking notifications. See <a href=\"https://docs.aws.amazon.com/gamelift/latest/flexmatchguide/match-notification.html\">\n                Setting up notifications for matchmaking</a> for more information.</p>"}))
    UpdateMatchmakingConfigurationInput.add_member(:additional_player_count, Smithy::Schema::Shapes::ShapeRef.new(shape: WholeNumber, location_name: 'AdditionalPlayerCount', traits: {"smithy.api#documentation" => "<p>The number of player slots in a match to keep open for future players. For example, if the configuration's rule set specifies \n            a match for a single 12-person team, and the additional player count is set to 2, only 10 players are selected for the match. This parameter is not used if <code>FlexMatchMode</code> is set to\n                <code>STANDALONE</code>.</p>"}))
    UpdateMatchmakingConfigurationInput.add_member(:custom_event_data, Smithy::Schema::Shapes::ShapeRef.new(shape: CustomEventData, location_name: 'CustomEventData', traits: {"smithy.api#documentation" => "<p>Information to add to all events related to the matchmaking configuration. </p>"}))
    UpdateMatchmakingConfigurationInput.add_member(:game_properties, Smithy::Schema::Shapes::ShapeRef.new(shape: GamePropertyList, location_name: 'GameProperties', traits: {"smithy.api#documentation" => "<p>A set of key-value pairs that can store custom data in a game session.\n  For example: <code>{\"Key\": \"difficulty\", \"Value\": \"novice\"}</code>. This information is added to the new <code>GameSession</code> object that is\n            created for a successful match. This parameter is not used if <code>FlexMatchMode</code>\n            is set to <code>STANDALONE</code>.</p>"}))
    UpdateMatchmakingConfigurationInput.add_member(:game_session_data, Smithy::Schema::Shapes::ShapeRef.new(shape: GameSessionData, location_name: 'GameSessionData', traits: {"smithy.api#documentation" => "<p>A set of custom game session properties, formatted as a single string value. This data is passed to a game server process with a request to start a new game session. For more information, see <a href=\"https://docs.aws.amazon.com/gamelift/latest/developerguide/gamelift-sdk-server-api.html#gamelift-sdk-server-startsession\">Start a game session</a>. This information is added to the game session\n            that is created for a successful match. This parameter is not used if\n                <code>FlexMatchMode</code> is set to <code>STANDALONE</code>.</p>"}))
    UpdateMatchmakingConfigurationInput.add_member(:backfill_mode, Smithy::Schema::Shapes::ShapeRef.new(shape: BackfillMode, location_name: 'BackfillMode', traits: {"smithy.api#documentation" => "<p>The method that is used to backfill game sessions created with this matchmaking\n            configuration. Specify MANUAL when your game manages backfill requests manually or does\n            not use the match backfill feature. Specify AUTOMATIC to have GameLift create a match backfill\n            request whenever a game session has one or more open\n            slots. Learn more about manual and automatic backfill in <a href=\"https://docs.aws.amazon.com/gamelift/latest/flexmatchguide/match-backfill.html\">Backfill Existing Games\n                with FlexMatch</a>. Automatic backfill is not available when\n                <code>FlexMatchMode</code> is set to <code>STANDALONE</code>.</p>"}))
    UpdateMatchmakingConfigurationInput.add_member(:flex_match_mode, Smithy::Schema::Shapes::ShapeRef.new(shape: FlexMatchMode, location_name: 'FlexMatchMode', traits: {"smithy.api#documentation" => "<p>Indicates whether this matchmaking configuration is being used with Amazon GameLift Servers hosting or\n            as a standalone matchmaking solution. </p>\n         <ul>\n            <li>\n               <p>\n                  <b>STANDALONE</b> - FlexMatch forms matches and\n                    returns match information, including players and team assignments, in a <a href=\"https://docs.aws.amazon.com/gamelift/latest/flexmatchguide/match-events.html#match-events-matchmakingsucceeded\"> MatchmakingSucceeded</a> event.</p>\n            </li>\n            <li>\n               <p>\n                  <b>WITH_QUEUE</b> - FlexMatch forms matches and uses\n                    the specified Amazon GameLift Servers queue to start a game session for the match. </p>\n            </li>\n         </ul>"}))
    UpdateMatchmakingConfigurationInput.type = Types::UpdateMatchmakingConfigurationInput
    UpdateMatchmakingConfigurationOutput.add_member(:configuration, Smithy::Schema::Shapes::ShapeRef.new(shape: MatchmakingConfiguration, location_name: 'Configuration', traits: {"smithy.api#documentation" => "<p>The updated matchmaking configuration.</p>"}))
