    UpdateRuntimeConfigurationInput.add_member(:runtime_configuration, Smithy::Schema::Shapes::ShapeRef.new(shape: RuntimeConfiguration, location_name: 'RuntimeConfiguration', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>Instructions for launching server processes on fleet computes. Server processes run\n            either a custom game build executable or a Amazon GameLift Servers Realtime script. The runtime configuration lists\n            the types of server processes to run, how to launch them, and the number of processes to\n            run concurrently.</p>", "smithy.api#required" => {}}))
